        { 377, "A", 22, 26, "米爾斯迪普議員", "暮色森林 - 夜色鎮 72,47", nil, false, nil, {2033, 2906}, "殺死迪克斯特·瓦德，把他的手帶回去給夜色鎮的米爾斯迪普議員作證明。", "迪克斯特·瓦德在副本內。", {{22,2}, {24,3}, {29,4}, {34,5}}, {3628}, nil, 270, "議員米爾斯迪普", { xp = 2100, rep = { {72, 100, "暴風城"} } } },
