        { 386, "A", 22, 25, "衛兵伯爾頓", "赤脊山 - 湖畔鎮 26,46", nil, false, nil, {3400, 1317}, "把塔格爾的頭顱帶給湖畔鎮的衛兵伯爾頓。", "塔格爾在副本內。塔格爾通常刷在中央區右手第一間或左手第二間牢房，偶爾刷在左右兩翼之間最北端的牢房。", {{22,2}, {23,3}, {28,4}, {33,5}}, {3630}, nil, 859, "衛兵伯爾頓", { xp = 2000, rep = { {72, 100, "暴風城"} } } },
        { 387, "A", 22, 26, "典獄官塞爾沃特", "暴風城 - 監獄 51,69", nil, false, nil, nil, "替暴風城典獄官塞爾沃特清點監獄：殺 10 名迪菲亞囚徒、8 名迪菲亞罪犯、8 名迪菲亞叛軍。", "任務由副本外的典獄官發放。", {{22,2}, {24,3}, {29,4}, {34,5}}, nil, nil, 1719, "典獄官塞爾沃特", { xp = 2650, money = 4000, rep = { {72, 150, "暴風城"} } } },
