    ["city_of_dalaran"] = {
        { 92457, "A", 24, 33, "大法師莫德拉的影像", "奧特蘭克山脈 - 達拉然城副本外", nil, false, nil, {279837, 279838}, "替達拉然城外的大法師莫德拉，擊殺城內的覓索殘跡（Seeking Remnant）×8、飽和殘跡（Saturated Remnant）×8、法力迴響（Mana Echo）×8。", "起始在副本外（大法師莫德拉的影像），開始並結束於同處。三種奧術元素怪都在達拉然城內：覓索殘跡、飽和殘跡、法力迴響。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 269127, "大法師莫德拉的影像", { xp = 9400, rep = { {2740, 100, "肯瑞托"} } } },
        { 92489, "A", 24, 33, "高階巫師安多瑪斯", "暴風城 - 法師區", nil, false, nil, {251962, 279849}, "替暴風城的高階巫師安多瑪斯，消滅達拉然城內的奧術之謎（Arcanic Enigma）。", "起始並結束於暴風城法師區的高階巫師安多瑪斯。奧術之謎是復甦之路上的精英怪，會沉默 10 秒並召喚奧術法力苗。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 5694, "高階巫師安多瑪斯", { xp = 9400 } },
        { 92432, "A", 30, 33, "使者雅克", "希爾斯布萊德丘陵 - 南海鎮", "緊急求援", false, nil, nil, "向達拉然城附近的大法師莫德拉的影像彙報。", "在希爾斯布萊德丘陵南海鎮的使者雅克處接取（可共享）。聯盟鏈：緊急求援（使者雅克→莫德拉的影像）→ 動亂之源（莫德拉的影像處接取，進城收集奧術微粒，自動發放「達拉然下水道鑰匙」）→ 肯瑞托之友（莫德拉的影像處接取，交付給紫羅蘭城堡的大法師塞林德拉）。", {{30,1}, {31,2}, {36,3}, {42,4}}, nil, nil, 247264, "使者雅克", { xp = 660 } },
        { 92458, "A", 24, 33, "大法師莫德拉的影像", "銀松森林 - 達拉然城副本外", "動亂之源", false, {92432}, {279839, 279840, 279841}, "為達拉然城外的大法師莫德拉的影像，取回城內的奧術微粒。", "接取並交付都在副本外的大法師莫德拉的影像。聯盟鏈：緊急求援（南海鎮使者雅克接取，彙報到莫德拉的影像處）→ 本任務（進城收集奧術微粒）→ 肯瑞托之友（莫德拉的影像處接取，交付給紫羅蘭城堡的大法師塞林德拉）。接本任務即自動發放「達拉然下水道鑰匙」。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {277507}, nil, 269127, "大法師莫德拉的影像", { xp = 9400, rep = { {2740, 100, "肯瑞托"} } } },
        { 92459, "A", 24, 33, "大法師莫德拉的影像", "銀松森林 - 達拉然城副本外", "肯瑞托之友", false, {92458}, nil, "帶着奧術微粒回到達拉然城，與大法師塞林德拉談談。", "在大法師莫德拉的影像處接取，任務提供「奧術微粒」。進城交付給紫羅蘭城堡的大法師塞林德拉；若聯盟被攔在城外，則在副本入口外交付。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {251961}, nil, 269127, "大法師莫德拉的影像", { xp = 265 } },
        { 92456, "A", 24, 33, "莎拉米爾", "暴風城 - 法師區", nil, false, nil, {279835, 279836}, "為暴風城的莎拉米爾，從達拉然城採回一朵注入邪能的花朵。", "起始並結束於暴風城法師區的莎拉米爾。注入邪能的花朵出自城內邪能植被，多半在邪能古樹一帶。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 5502, "莎拉米爾", { xp = 9400 } },
        { 96986, "H", 24, 33, "梅里薩拉", "希爾斯布萊德丘陵 - 塔倫米爾", nil, false, nil, {251963, 251965}, "替塔倫米爾的梅里薩拉，擊敗達拉然城內的墓穴騎士阿特雷克斯。", "起始並結束於塔倫米爾的梅里薩拉。阿特雷克斯在下水道深處的儀式法陣；他會繳械當前目標 —— 坦克被繳械期間注意減傷。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 2278, "梅里薩拉", { xp = 9400 } },
        { 96988, "H", 24, 33, "馬丁·費爾本", "幽暗城 - 鍊金區", nil, false, nil, {279847, 279848}, "為幽暗城的馬丁·費爾本，從達拉然城收集 6 枚開裂的哨兵核心。", "起始並結束於幽暗城的馬丁·費爾本。開裂的哨兵核心多半由城內奧術魔像/哨兵造型怪掉落。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, 11044, "馬丁·費爾本", { xp = 9400 } },
        { 92434, "H", 30, 34, "大法師沃迪恩·伍德格萊爾", "希爾斯布萊德丘陵 - 塔倫米爾", "喋血街頭", false, nil, nil, "沿洛丹倫湖尋找進入達拉然城的辦法。", "在塔倫米爾的大法師沃迪恩·伍德格萊爾處接取（需先完成他發放的其餘任務），任務提供「骯髒的鑰匙」。沿洛丹倫湖岸找到達拉然城北緣的下水道入口潛入城中，交付給城外的大法師莫德拉的影像。", {{30,1}, {32,2}, {37,3}, {43,4}}, {279469}, nil, 2410, "大法師沃迪恩·伍德格萊爾", { xp = 270 } },
        { 96984, "H", 24, 33, "大法師莫德拉的影像", "銀松森林 - 達拉然城副本外", "動亂之源", false, {92434}, {279842, 279843, 279844}, "為塔倫米爾的大法師沃迪恩·伍德格萊爾，取回達拉然城內的奧術微粒。", "接取在副本外的大法師莫德拉的影像處，交付回塔倫米爾的沃迪恩·伍德格萊爾。部落鏈：喋血街頭（塔倫米爾接取，潛入達拉然，交付在莫德拉的影像處）→ 本任務（進城收集奧術微粒）→ 精明的談判（回塔倫米爾接，交付給紫羅蘭城堡的大法師塞林德拉）。接本任務即自動發放「達拉然下水道鑰匙」。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {277507}, nil, 269127, "大法師莫德拉的影像", { xp = 9400 } },
        { 97287, "H", 24, 33, "大法師沃迪恩·伍德格萊爾", "希爾斯布萊德丘陵 - 塔倫米爾", "精明的談判", false, {96984}, nil, "帶着奧術微粒回到達拉然城，與大法師塞林德拉談談。", "在塔倫米爾的大法師沃迪恩·伍德格萊爾處接取，任務提供「奧術微粒」。交付給紫羅蘭城堡的大法師塞林德拉；若部落被攔在城外，則在副本入口外交付（即發鑰匙的莫德拉的影像處）。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, {251961}, nil, 2410, "大法師沃迪恩·伍德格萊爾", { xp = 270 } },
        { 96987, "H", 24, 33, "雷克西·銅鉗", "奧特蘭克山脈 - 達拉然城下水道入口附近", nil, false, nil, nil, "從達拉然城取回《達拉然的建立》，交給下水道入口附近的雷克西·銅鉗。", "發佈者雷克西·銅鉗守在下水道入口附近。《達拉然的建立》是隊伍中每人都能拾取的任務物品 —— 一隊人可各自完成。", {{24,1}, {29,2}, {31,3}, {36,4}, {42,5}}, nil, nil, nil, "雷克西·銅鉗", { xp = 9400 } },
    },
    ["gnomeregan"] = {
        { 2843, "H", 20, 35, "斯庫提", "荊棘谷 - 藏寶海灣 27,77", "主工程師斯庫提", false, {2842}, {9173}, "等斯庫提把地精傳送器調好。", "前置可從索維克(奧格瑞瑪-榮譽谷 75,25)接。完成後就能使用藏寶海灣的傳送器。◎ 哥布林轉發器用完可以丟掉，丟了再找斯庫提說一聲就能再領一個。", {{20,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7853, "斯庫提", nil },
        { 2922, "A", 20, 26, "工匠大師歐沃斯巴克", "鐵爐堡 - 侏儒區 69,50", "工匠大師歐沃斯巴克", false, {2923}, nil, "把尖端機器人的存儲器核心交給鐵爐堡的工匠大師歐沃斯巴克。", "前置可從薩爾努修士接(暴風城-教堂廣場 51,48)。尖端機器人在進副本前、後門附近。", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {9277}, nil, 7944, "工匠大師歐沃斯巴克", { xp = 2650, money = 2000, rep = { {54, 150, "諾莫瑞根流亡者"} } } },
        { 2926, "A", 20, 27, "奧齊·電環", "丹莫羅 - 卡拉諾斯 45,49", "災難之後", false, {2927}, nil, "用空鉛瓶從輻射入侵者或輻射搶劫者身上收集放射塵，裝滿後交給卡拉諾斯的奧齊·電環。", "前置可從諾恩接(鐵爐堡-侏儒區 69,50)。取樣方法：對活着的輻射入侵者/搶劫者使用空鉛瓶。", {{20,1}, {23,2}, {25,3}, {30,4}, {35,5}}, {9284, 9283}, nil, 1268, "奧齊·電環", { xp = 2200, money = 2200, rep = { {54, 100, "諾莫瑞根流亡者"} } } },
        { 2928, "A", 20, 30, "沉默的舒尼", "暴風城 - 矮人區 63,34", nil, false, nil, {9608, 9609, 270045}, "收集 24 副機械內膽，交給暴風城的舒尼。", "所有機器人都掉內膽。", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9309}, nil, 6579, "沉默的舒尼", { xp = 2450, rep = { {72, 100, "暴風城"}, {54, 100, "諾莫瑞根流亡者"} } } },
        { 2962, "A", 20, 30, "奧齊·電環", "丹莫羅 - 卡拉諾斯 45,49", "諾恩", false, {2926}, nil, "到諾莫瑞根收集高強度輻射塵（極不穩定、會很快分解），並把沉重的鉛瓶一併交還奧齊。", "取樣方法：對活着的輻射泥漿怪、輻射潛伏者、輻射水元素使用沉重的鉛瓶。", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9365, 9364}, nil, 1268, "奧齊·電環", { xp = 2450, money = 2500 } },
        { 2904, nil, 24, 30, "克努比", "諾莫瑞根", nil, true, nil, {9535, 9536, 270042}, "把克努比護送到出口，然後回藏寶海灣向斯庫提彙報。", "護送任務。斯庫提(荊棘谷-藏寶海灣 27,77)。護送終點是副本正門（送到門口即可，不用穿出去）；小侏儒不會主動引怪，潛行職業全程潛行也能做。", {{20,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 7850, "克努比", { xp = 2450 } },
        { 2924, "A", 24, 30, "科勞莫特·鋼尺", "鐵爐堡 - 侏儒區 68,46", "幫助科勞莫特", false, {2925}, nil, "收集 12 個基礎模組，交給鐵爐堡的科勞莫特·鋼尺。", "前置可從瑪希爾接(達納蘇斯-戰士區 59,45)。諾莫瑞根的所有敵人都可能掉。", {{24,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {9278}, nil, 6169, "科羅莫特·鋼尺", { xp = 3050, money = 5500, rep = { {54, 150, "諾莫瑞根流亡者"} } } },
        { 2841, "H", 25, 35, "諾格", "奧格瑞瑪 - 榮譽谷 75,25", nil, false, nil, {9623, 9624, 9625}, "從諾莫瑞根取回鑽探設備藍圖和麥克尼爾的保險箱密碼，交給奧格瑞瑪的諾格。", "麥克尼爾·瑟瑪普拉格是諾莫瑞根最終 首領。戰鬥中記得按他旁邊的按鈕，阻止他丟炸彈。", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, {9153, 9299}, nil, 3412, "諾格", { xp = 2750, rep = { {76, 100, "奧格瑞瑪"} } } },
        { 2929, "A", 25, 35, "大工匠梅卡托克", "鐵爐堡 - 侏儒區 68,48", nil, false, nil, {9623, 9624, 9625}, "進入諾莫瑞根擊殺麥克尼爾·瑟瑪普拉格，完成後向大工匠梅卡托克報告。", "他是最終 首領。戰鬥中要按他旁邊的按鈕阻止他丟炸彈。", {{25,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 7937, "大工匠梅卡托克", { xp = 2750, money = 3500, rep = { {54, 100, "諾莫瑞根流亡者"} } } },
