    ["razorfen_kraul"] = {
        { 1221, nil, 20, 26, "麥伯克·米希瑞克斯", "貧瘠之地 - 棘齒城 62,37", nil, false, nil, {6755}, "湊齊開孔的箱子、地鼠指揮棒和《地鼠指揮手冊》；在剃刀沼澤用箱子召喚地鼠並驅使它搜出藍葉薯；最後把指揮棒、箱子和 10 塊藍葉薯一起交給棘齒城的麥伯克·米希瑞克斯。", "箱子和手冊都能在麥伯克·米希瑞克斯附近找到。", {{20,1}, {22,2}, {24,3}, {29,4}, {34,5}}, {5876, 5880, 5897, 6684}, nil, 3446, "麥伯克·米希瑞克斯", { xp = 2100, rep = { {470, 100, "棘齒城"} } } },
