        { 1144, nil, 23, 30, "進口商威利克斯", "剃刀沼澤", nil, true, nil, {6748, 6750, 6749}, "護送進口商威利克斯逃出剃刀沼澤。", "護送時離他太遠或太近都會判失敗。進本右手穿過野豬區即到威利克斯，無需清任何首領。", {{22,1}, {26,2}, {28,3}, {33,4}, {38,5}}, nil, nil, 4508, "進口商威利克斯", { xp = 3050, rep = { {470, 150, "棘齒城"} } } },
        { 1142, "A", 25, 30, "赫爾拉斯·靜水", "剃刀沼澤", nil, true, nil, {6751, 6752}, "找回塔莎拉的墜飾並交還給達納蘇斯的塔莎拉·靜水。", "墜飾為隨機掉落。交回地點：塔莎拉·靜水(達納蘇斯-貿易區 69,67)。", {{25,1}, {26,2}, {28,3}, {33,4}, {38,5}}, {5825}, nil, 4510, "赫爾拉斯·靜水", { xp = 3050, rep = { {69, 150, "達納蘇斯"} } } },
