    ["razorfen_downs"] = {
        { 6521, "H", 28, 36, "瓦里瑪薩斯", "幽暗城 - 皇家區 56,92", "邪惡的盟友", false, {6522}, {17039, 17042, 17043}, "把瑪克林大使的頭顱帶給幽暗城的瓦里瑪薩斯。", "前置由剃刀沼澤的最終首領給出。瑪克林大使在進副本前的空地上(貧瘠之地-剃刀高地 48,92)。", {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17009}, nil, 2425, "瓦里瑪薩斯", { xp = 3500, money = 2000 } },
        { 6522, "H", 28, 36, "由物品[小卷軸]起始", nil, nil, false, nil, nil, nil, nil, {{28,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {17008}, nil, nil, nil, { xp = 2800, money = 4000 } },
        { 6626, nil, 28, 35, "麥雷姆·月歌", "貧瘠之地 - 剃刀高地 49,94", nil, false, nil, nil, "殺 8 個剃刀沼澤護衛者、8 個剃刀沼澤織棘者和 8 個亡首教徒，向剃刀高地入口處的麥雷姆·月歌覆命。", "這三種怪都在進副本前經過的路上。", {{28,1}, {31,2}, {33,3}, {38,4}, {44,5}}, nil, nil, 12866, "麥雷姆·月歌", { xp = 3450, money = 7500 } },
        { 3523, nil, 32, 37, "奔尼斯特拉茲", nil, nil, true, nil, nil, nil, "這不是護送任務本體——先完成它，之後纔會開放真正的護送任務《撲滅聖火之儀》。確保全隊都完成本任務後再進護送段，否則沒完成的人拿不到後續。", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, {10682}, nil, 8516, "奔尼斯特拉茲", { xp = 285 } },
        { 3525, nil, 32, 37, "奔尼斯特拉茲", "剃刀高地", "剃刀高地的亡靈天災", true, {3523}, {10710}, "陪奔尼斯特拉茲到剃刀高地的野豬人神像處，在他儀式封印神像時保護他。", "接受協助後儀式期間會不斷刷怪攻擊他，保證他不倒；完成後在神像前交付領獎。", {{32,1}, {33,2}, {35,3}, {40,4}, {46,5}}, nil, nil, 8516, "奔尼斯特拉茲", { xp = 4250 } },
        { 3341, "H", 37, 42, "安德魯·布隆奈爾", "幽暗城 - 魔法區 72,32", nil, false, nil, {10823, 10824}, "替安德魯·布隆奈爾擊殺寒冰之王亞門納爾，帶回他的頭骨。", "寒冰之王亞門納爾是剃刀高地的最終 首領。", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {10420}, nil, 2308, "安德魯·布隆奈爾", { xp = 4300, rep = { {68, 150, "幽暗城"} } } },
        { 3636, "A", 39, 42, "大主教本尼迪塔斯", "暴風城 - 光明大教堂 50,45", nil, false, nil, {10823, 10824}, "替大主教本尼迪塔斯擊殺剃刀高地的寒冰之王亞門納爾。", "他是剃刀高地的最終首領。★ 本任務不可共享，隊裏每個人都要自己接。", {{39,2}, {40,3}, {45,4}, {52,5}}, nil, nil, 1284, "大主教本尼迪塔斯", { xp = 4300, rep = { {72, 150, "暴風城"} } } },
