    ["uldaman"] = {
        { 1192, nil, 29, nil, "普茲克", "千針石林 - 沙漠賽道 80.1, 75.9", "瑞茲爾的圖表", false, {1194}, nil, "為千針石林的普茲克收集 4 塊精鐵礦石。", "前置完成後的可重複任務，只給少量金錢，無聲望經驗。礦石可在奧達曼內採礦獲得，也能從玩家處買。", {{29,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {5833}, nil, 4630, "普茲克", nil },
        { 704, "A", 30, 38, "勘察員基恩薩·鐵環", "洛克莫丹 - 鐵環挖掘場 65,65", "莫達洛克", false, {739}, {4980}, "收集 4 個雕紋石罐，交給洛克莫丹的勘察員基恩薩·鐵環。", "系列始於勘察員塔伯斯·雷矛(鐵爐堡-探險者大廳 74,12)。石罐散落在副本前的山洞裏。", {{30,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {4610}, nil, 1344, "勘察員基恩薩·鐵環", { xp = 2850, rep = { {47, 100, "鐵爐堡"} } } },
        { 709, nil, 30, 40, "迷失者塞爾杜林", "荒蕪之地 51,76", nil, false, nil, {4746}, "把雷烏納石板帶給迷失者塞爾杜林。", "石板在洞穴北端通道盡頭。", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {4631}, nil, 2785, "迷失者塞爾杜林", { xp = 3150 } },
        { 2418, nil, 30, 36, "裏格弗茲", "荒蕪之地 42,52", nil, false, nil, {9522, 10358, 10359}, "為荒蕪之地的裏格弗茲收集 8 塊德提亞姆能量石和 8 塊安納洛姆能量石。", "副本內外的暗爐系敵人都掉能量石。不用進副本——在進本前的挖掘場打暗爐矮人就能攢齊。", {{30,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {8009, 8052}, nil, 2817, "裏格弗茲", { xp = 3500, rep = { {21, 150, "藏寶海灣"}, {87, 750, "血帆海盜"} } } },
        { 1360, "A", 33, 43, "克羅姆·粗臂", "鐵爐堡 - 探險者大廳 74,9", nil, false, nil, nil, "到奧達曼北部大廳找到克羅姆·粗臂的箱子，取出裏面的財物，帶回鐵爐堡交給他。", "財物在進副本前的洞穴裏，北面第一條通道東南角盡頭。", {{33,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {8027}, nil, 6294, "克羅姆·粗臂", { xp = 3600, money = 6000, rep = { {47, 100, "鐵爐堡"} } } },
        { 2342, "H", 33, 43, "帕特里克·加瑞特", "幽暗城 72,48", nil, false, nil, nil, "從奧達曼南部大廳的箱子裏找回加勒特的家族寶藏，交給幽暗城的帕特里克·加瑞特。", "寶藏進副本前就能拿到，在南部通道盡頭。", {{33,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {8026}, nil, 5651, "帕特里克·加瑞特", { xp = 3600, money = 6000, rep = { {68, 100, "幽暗城"} } } },
        { 721, "A", 35, nil, "勘察員雷杜爾", "荒蕪之地 53,43", "一線希望", false, {720}, nil, "進入奧達曼找到鐵趾格雷茲。", "系列始於一張弄皺的地圖(荒蕪之地 53,33)。鐵趾格雷茲在副本入口附近。", {{35,3}, {38,4}, {44,5}}, nil, nil, 2910, "勘察員雷杜爾", nil },
        { 722, "A", 35, 40, "鐵趾格雷茲", "奧達曼 副本入口地圖）。", "一線希望", false, {721}, nil, "找回鐵趾的護符，交給奧達曼的鐵趾格雷茲。", "護符由馬格雷甘·深影掉落。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {4635}, nil, 2909, "鐵趾格雷茲", { xp = 3150, rep = { {47, 100, "鐵爐堡"} } } },
        { 1139, "A", 35, 45, "顧問貝爾格拉姆", "鐵爐堡 - 探險者大廳 77,10", "邪惡的使者", false, {762}, {6723}, "找到意志石板，交給鐵爐堡的顧問貝爾格拉姆。", "石板在副本內，就在加加恩·火錘身旁。", {{35,1}, {41,2}, {43,3}, {48,4}, {55,5}}, {5824}, nil, 2918, "顧問貝爾格拉姆", { xp = 5850, money = 13000, rep = { {47, 200, "鐵爐堡"} } } },
        { 1956, nil, 35, nil, "塔貝薩", "塵泥沼澤 46,57", "驅除魔鬼", false, {1955}, nil, "找到一個黑曜石能量源，交給塵泥沼澤的塔貝薩。", "僅法師可做！能量源由黑曜石哨兵掉落。黑曜石哨兵就在後門裏——從後門(荒蕪之地 67,44)進去第一眼就能看到，沒有小怪護衛。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {8053}, "法師", 6546, "塔貝薩", nil },
        { 2240, "A", 35, 40, "巴爾洛戈", "奧達曼", "失蹤的矮人", true, {2398}, {9626, 9627}, "讀完巴爾洛戈的日記、探明密室，回鐵爐堡向勘察員塔伯斯·雷矛彙報。", "密室在副本內。開門流程：從魯維羅什拿索爾之杖，從巴爾洛戈的箱子拿尼基夫徽章，合成史前法杖；再到兩間房之間的地圖室召喚艾隆納亞，擊敗後進入密室。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 6906, "巴爾洛戈", { xp = 3900, rep = { {47, 150, "鐵爐堡"} } } },
        { 2398, "A", 35, nil, "勘察員塔伯斯·雷矛", "鐵爐堡 - 探險者大廳 75,12", nil, false, nil, nil, "到奧達曼找到巴爾洛戈。", "巴爾洛戈在副本內。引導任務：若已接受或完成《隱藏的密室》，本任務將無法完成。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 1356, "勘察員塔伯斯·雷矛", nil },
        { 17, "A", 36, 42, "加克", "洛克莫丹 - 塞爾薩瑪 37,49", "荒蕪之地的材料", false, {2500}, {9030}, "採到 12 顆紫色蘑菇，帶回塞爾薩瑪交給加克。", "蘑菇（品紅菌蓋）散落在進本前的洞穴裏（不在副本內），多在火堆旁和帳篷後面；學了草藥學開追蹤會在小地圖上標出。前置任務同樣在這名 NPC 處接。", {{38,2}, {40,3}, {45,4}, {52,5}}, {8047}, nil, 1470, "加克", { xp = 3450, money = 5500, rep = { {47, 100, "鐵爐堡"} } } },
        { 2202, "H", 36, 42, "加卡爾", "荒蕪之地 - 卡加斯 2,69", "荒蕪之地的試劑", false, {2258}, {9030}, "收集 12 顆紫色蘑菇，交給卡加斯的加卡爾。", "前置同樣在加卡爾處接。蘑菇散落副本各處；開草藥追蹤的小地圖會直接標出。", {{36,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {8047}, nil, 6868, "加卡爾", { xp = 3450, money = 5500, rep = { {530, 100, "暗矛巨魔"} } } },
        { 2198, "A", 37, 41, "破碎的項鍊", "奧達曼內隨機掉落", nil, false, nil, nil, "查清破碎項鍊的來歷，評估它的價值。", "把項鍊帶給鐵爐堡的塔瓦斯德·基瑟爾(鐵爐堡-祕法區 36,3)。", {{37,2}, {39,3}, {44,4}, {51,5}}, {7666}, nil, nil, nil, { xp = 3300 } },
        { 2199, "A", 37, 41, "塔瓦斯德·基瑟爾", "丹莫羅", nil, false, {2198}, nil, nil, nil, {{37,2}, {39,3}, {44,4}, {51,5}}, {2842}, nil, 6826, "塔瓦斯德·基瑟爾", { xp = 2450, rep = { {54, 75, "諾莫瑞根流亡者"} } } },
        { 2200, "A", 37, nil, "塔瓦斯德·基瑟爾", "鐵爐堡 - 祕法區 36,3", "昂貴的知識", false, {2199}, nil, "到奧達曼尋找塔瓦斯的魔法項鍊——死去的聖騎士是最後一個持有者。", "那名聖騎士在副本內：遺體在守護者大廳（第一個「8」字形區域）的西北角，頭頂黃問號、無需搜尋互動。", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7667}, nil, 6826, "塔瓦斯德·基瑟爾", nil },
        { 2204, "A", 37, 44, "塔瓦斯德的占卜之碗", "塔瓦斯德的占卜之碗", "尋找寶石", true, {2201}, nil, "從奧達曼最強的石人身上取得能量源，交給鐵爐堡的塔瓦斯德。", "破碎項鍊的能量源由阿扎達斯掉落。", {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, {7672}, nil, nil, nil, { xp = 930 } },
        { 2283, "H", 37, 41, "德蘭·杜佛斯", "奧格瑞瑪 - 暗巷區 59,36", nil, false, nil, nil, "在奧達曼挖掘場找一條珍貴的項鍊（可能已損壞），交給奧格瑞瑪的德蘭·杜佛斯。", "項鍊是副本內隨機掉落。", {{37,2}, {39,3}, {44,4}, {51,5}}, {7666}, nil, 6986, "德蘭·杜佛斯", { xp = 2450, rep = { {76, 75, "奧格瑞瑪"} } } },
        { 2284, "H", 37, nil, "德蘭·杜佛斯", "奧格瑞瑪 - 暗巷區 59,36", "搜尋項鍊", false, {2283}, nil, "到奧達曼尋找與寶石有關的線索。", "那名聖騎士在副本內：進本後一直右手貼牆走就能到遺體處。", {{37,2}, {39,3}, {44,4}, {51,5}}, nil, nil, 6986, "德蘭·杜佛斯", nil },
        { 2318, "H", 37, nil, "聖騎士的遺體", "奧達曼", "搜尋項鍊，再來一次", false, {2284}, nil, "在荒蕪之地卡加斯哨所找一個能翻譯聖騎士日記的人。", "人選是加卡爾(荒蕪之地-卡加斯 2,46)；把項鍊借給他即可完成翻譯。", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7886}, nil, 6912, "聖騎士的遺體", nil },
