        { 2361, "A", 37, 44, "塔瓦斯德·基瑟爾", "丹莫羅", nil, false, {2204}, {7673}, nil, nil, {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, nil, nil, 6826, "塔瓦斯德·基瑟爾", { xp = 5600, rep = { {54, 200, "諾莫瑞根流亡者"} } } },
        { 2201, "A", 40, 43, "聖騎士的遺體", "奧達曼", "回到奧達曼", true, {2200}, nil, "在奧達曼查明紅寶石、藍寶石、黃寶石的下落，用塔瓦斯德給的占卜之瓶向他反饋。", "寶石分別在副本內的顯眼石罐、暗影熔爐地窖，以及格瑞姆洛克身上。注意：打開暗影熔爐地窖會刷怪。", {{37,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {7669, 7670, 7671, 7668}, nil, 6912, "聖騎士的遺體", { xp = 3600 } },
        { 2278, nil, 40, nil, "諾甘農圓盤", "奧達曼", nil, false, nil, nil, "向石頭守護者瞭解古代知識，隨後激活諾甘農圓盤；再把迷你版諾甘農圓盤帶回鐵爐堡探險者協會。", "接任務後先與石頭守護者旁的圓盤對話，再用白金圓盤取得縮小版，交給資深探險家麥格拉斯(鐵爐堡-探險者大廳 69,18)。後續任務在旁邊 NPC 處接。", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, nil, nil, nil, nil, nil },
        { 2279, "A", 40, 47, "諾甘農圓盤", nil, "白金圓盤", true, nil, nil, nil, nil, {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {6064}, nil, nil, nil, { xp = 5250, rep = { {47, 150, "鐵爐堡"} } } },
        { 2280, "H", 40, 47, "諾甘農圓盤", nil, "白金圓盤", true, {2278}, nil, nil, "殺掉阿扎達斯後進入其身後的寶庫，點底座上的圓盤接任務；聽召喚出的幽靈講完全部故事後，再點一次圓盤拿到縮小版——漏了這步就得重跑一趟。回雷霆崖交任務(NPC 在 35,47 附近)。", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {6064}, nil, nil, nil, { xp = 5250, rep = { {81, 150, "雷霆崖"} } } },
