    ["zul_farrak"] = {
        { 2768, nil, 40, 47, "比格維茲", "塔納利斯 - 加基森 52,28", nil, false, nil, {9533, 9534}, "把探水棒交給加基森的首席工程師沙克斯·比格維茲。", "探水棒來自布萊中士。要先把神廟的百人斬事件打完、擊敗布萊中士才能拿到。", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {8548}, nil, 7407, "首席工程師沙克斯·比格維茲", { xp = 6300, rep = { {369, 200, "加基森"} } } },
