        { 3527, nil, 40, 47, "葉基亞", "塔納利斯 - 熱砂港 66,22", "尖嘯者的靈魂", false, {3520}, nil, "把第一、第二塊摩沙魯石板交給塔納利斯的葉基亞。", "前置同樣在葉基亞處接。石板分別由殉教者塞卡和水佔師維蕾薩掉落。", {{40,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {10660, 10661}, nil, 8579, "葉基亞", { xp = 5250 } },
