        { 7041, "A", 41, 47, "塔琳德莉亞", "淒涼之地 - 尼耶爾前哨站 68,8", nil, false, nil, {17768, 17778, 17770}, "用天藍水瓶在瑪拉頓的橙色水晶池裝水，澆在維利斯塔姆藤蔓上引出墮落的諾克賽恩幼體；治療 8 株植物並殺掉幼體，回尼耶爾前哨站向塔琳德莉亞覆命。", "裝水用副本外帶橙色水晶的大水池（不是小仙女站的那個小池）；藤蔓在橙色區域，對花使用瓶子會召喚出花與元素，都殺掉後全隊共享完成。", {{41,1}, {43,2}, {45,3}, {50,4}, {57,5}}, {17696, 17693}, nil, 11715, "塔琳德莉亞", { xp = 5250 } },
        { 7044, nil, 41, 49, "凱雯德拉", "淒涼之地 - 瑪拉頓 副本入口地圖", nil, false, nil, nil, "找回塞雷布拉斯節杖的兩個部件——塞雷布拉斯魔棒和塞雷布拉斯鑽石——然後設法與塞雷布拉斯對話。", "凱雯德拉就在進副本前的橙色區域起點。魔棒來自諾克塞恩，鑽石來自維利塔恩。塞雷布拉斯在副本內，要先擊敗他才能對話。", {{41,1}, {45,2}, {47,3}, {52,4}, {59,5}}, {17703, 17702}, nil, 13697, "凱雯德拉", { xp = 3400 } },
        { 7046, nil, 41, 49, "贖罪的塞雷布拉斯", "瑪拉頓", "瑪拉頓的傳說", true, {7044}, {17191}, "幫助贖罪的塞雷布拉斯製作塞雷布拉斯節杖，儀式完成後與他再談一次。", "節杖由塞雷布拉斯親手製作；儀式結束後與他對話即可。杖丟了可以再殺塞雷布拉斯，與他對話選「我丟了節杖」重新領取。", {{41,1}, {45,2}, {47,3}, {52,4}, {59,5}}, nil, nil, 13716, "贖罪的塞雷布拉斯", { xp = 5700 } },
        { 7064, "H", 45, 51, "瑟琳德拉", "淒涼之地 - 葬影村 27,77", nil, false, nil, {17705, 17743, 17753}, "殺死瑟萊德絲公主，回淒涼之地葬影村附近向瑟琳德拉覆命。", "瑟萊德絲公主在副本內。", {{45,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 13699, "瑟琳德拉", { xp = 6100, rep = { {609, 150, "塞納里奧議會"} } } },
        { 7065, "A", 45, 51, "守護者瑪蘭迪斯", "淒涼之地 - 尼耶爾前哨站 63,10", nil, false, nil, {17705, 17743, 17753}, "殺死瑟萊德絲公主，回淒涼之地尼耶爾前哨站向守護者瑪蘭迪斯覆命。", "瑟萊德絲公主在副本內。", {{45,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 13698, "守護者瑪蘭迪斯", { xp = 6100, rep = { {609, 150, "塞納里奧議會"} } } },
        { 7066, nil, 45, 51, "扎爾塔的靈魂", "瑪拉頓", "大地的污染", true, {"大地的污染"}, nil, "到月光林地找到雷姆洛斯，把生命之種交給他。", "殺死公主後扎爾塔的靈魂會出現。雷姆洛斯(月光林地-雷姆洛斯神殿 36,41)。", {{39,1}, {47,2}, {49,3}, {54,4}, {62,5}}, {17760}, nil, 12238, "扎爾塔的靈魂", { xp = 6100, money = 15000, rep = { {609, 150, "塞納里奧議會"} } } },
