    ["sunken_temple"] = {
        { 1445, "H", 38, 50, "費澤魯爾", "悲傷沼澤 - 斯通納德 47,54", "向費澤魯爾覆命", false, {1444}, {1490}, "收集 20 個哈卡神像，交給斯通納德的費澤魯爾。", "神廟內所有敵人都會掉神像。", {{38,1}, {46,2}, {48,3}, {53,4}, {61,5}}, {6181}, nil, 1443, "費澤魯爾", { xp = 5900, rep = { {76, 150, "奧格瑞瑪"} } } },
        { 1446, nil, 38, 53, "阿塔萊流放者", "辛特蘭 33,75", nil, false, nil, {11123, 11124}, "帶回迦瑪蘭的頭，交給辛特蘭的阿塔萊流放者。", "迦瑪蘭在副本內。要先清掉陽臺上的一圈幽靈（守結界的亡靈巨魔）才能開打迦瑪蘭。", {{38,1}, {49,2}, {51,3}, {56,4}, {64,5}}, {6212}, nil, 5598, "阿塔萊流放者", { xp = 6550 } },
        { 3528, nil, 40, 53, "葉基亞", "塔納利斯 - 熱砂港 66,22", "遠古之卵", false, {4787}, {10749, 10750, 10751}, "把裝滿的哈卡之卵交給塔納利斯的葉基亞。", "系列始於《尖嘯者的靈魂》（同在本副本接）。到副本內的祭壇使用哈卡之卵觸發事件；刷出的敵人部分掉哈卡萊之血，用它熄滅不滅火焰，全部熄滅後哈卡化身降臨。", {{40,1}, {49,2}, {51,3}, {56,4}, {64,5}}, {10662, 10465}, nil, 8579, "葉基亞", { xp = 7900, money = 24000 } },
        { 1475, "A", 41, 50, "布羅哈恩·鐵桶", "暴風城 - 矮人區 69,40", "拉普索迪的故事", false, {1469}, {1490}, "為暴風城的布羅哈恩·鐵桶收集 10 塊阿塔萊石板。", "在本處接前置。石板進本前就能拿滿：門口大廳水下中央 1 塊、兩側桌上各 1 塊，約 8 分鐘刷新，等一等即可湊齊全隊。", {{38,1}, {46,2}, {48,3}, {53,4}, {61,5}}, {6288}, nil, 5384, "布羅哈恩·鐵桶", { xp = 7100, rep = { {47, 200, "鐵爐堡"} } } },
        { 3380, "H", 46, nil, "巫醫尤克里", "菲拉斯 74,43", nil, false, nil, nil, "到塔納利斯找到瑪爾馮·瑞文斯克。", "位置 52,45。", {{46,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 8115, "巫醫尤克里", nil },
        { 3445, "A", 46, nil, "安吉拉斯·月風", "菲拉斯 - 羽月要塞 31,45", nil, false, nil, nil, "到塔納利斯找到瑪爾馮·瑞文斯克。", "位置 52,45。", {{46,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 7900, "安吉拉斯·月風", nil },
        { 3446, nil, 46, 51, "瑪爾馮·瑞文斯克", "塔納利斯 52,45", "石環", false, {3444}, nil, "進入悲傷沼澤的沉沒神廟，找到哈卡祭壇。", "祭壇在圖中。進本右手下樓梯到「污穢之坑」，哈卡祭壇就在那裏。", {{46,1}, {47,2}, {49,3}, {54,4}, {62,5}}, {10466}, nil, 7771, "瑪爾馮·瑞文斯克", { xp = 4900 } },
        { 3447, nil, 46, 51, "瑪爾馮·瑞文斯克", "塔納利斯 52,45", "深入神廟", false, {3446}, {10773}, "進入沉沒神廟，破解雕像群隱藏的祕密。", "雕像群在副本內，開啓順序：南 → 北 → 西南 → 東南 → 西北 → 東北。", {{46,1}, {47,2}, {49,3}, {54,4}, {62,5}}, nil, nil, 7771, "瑪爾馮·瑞文斯克", { xp = 6100 } },
        { 4143, "A", 47, nil, "格雷甘·山酒", "菲拉斯 45,25", "造訪格雷甘", false, {4142}, nil, "收集 5 份阿塔萊之霧，回安戈洛環形山向穆爾金覆命。", "前置《穆爾金和拉瑞安》始於穆爾金(安戈洛環形山-馬紹爾營地 42,9)。神廟深淵潛伏者、黑暗蟲、融合軟泥怪都掉。必須進副本打——本外的軟泥怪不掉。進本右手下樓梯即到潛伏者/軟泥怪區。", {{47,1}, {48,2}, {50,3}, {55,4}, {63,5}}, {11318}, nil, 7775, "格雷甘·山酒", nil },
        { 4146, "H", 47, 52, "莉芙·雷茲菲克斯", "貧瘠之地 62,38", "瑪爾馮的車間", false, {4147}, nil, "收集 5 份阿塔萊之霧，送到馬紹爾營地的拉瑞安那裏。", "前置《拉瑞安和穆爾金》始於拉瑞安(安戈洛環形山 45,8)。神廟深淵潛伏者、黑暗蟲、軟泥怪都掉。必須進副本打——本外的軟泥怪不掉。進本右手下樓梯即到潛伏者/軟泥怪區。", {{47,1}, {48,2}, {50,3}, {55,4}, {63,5}}, {11319, 11318}, nil, 8496, "莉芙·雷茲菲克斯", { xp = 5100 } },
        { 3373, nil, 48, 55, nil, "伊蘭尼庫斯精華掉落自（伊蘭尼庫斯的陰影）", nil, false, nil, {10455}, "把伊蘭尼庫斯精華放進沉沒神廟裏他巢穴旁的精華之泉。", "精華由伊蘭尼庫斯的陰影掉落，精華之泉就在他旁邊。", {{48,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {10454}, nil, nil, nil, { xp = 2800 } },
        { 8232, nil, 50, nil, "奧汀克", "艾薩拉 42,43", "碎浪多頭怪", false, {8231}, nil, "把摩弗拉斯的牙齒交給艾薩拉的奧汀克——他住在埃達拉斯廢墟東北的懸崖頂上。", "獵人職業任務。摩弗拉斯在副本內。", {{50,3}, {55,4}, {63,5}}, {20019}, "獵人", 8405, "奧汀克", nil },
        { 8236, nil, 50, nil, "大法師克希雷姆", "艾薩拉 29,40", "密文碎片", false, {8235}, nil, "把碧藍鑰匙交給喬拉齊·拉文霍德公爵。", "盜賊職業任務。鑰匙由摩弗拉斯掉落。喬拉齊·拉文霍德公爵(奧特蘭克山谷-拉文霍德 86,79)。", {{50,3}, {55,4}, {63,5}}, {20022}, "盜賊", 8379, "大法師克希雷姆", nil },
        { 8253, nil, 50, nil, "大法師克希雷姆，摩弗拉斯", "艾薩拉 29,40", "納迦的珊瑚", false, {8252}, nil, "從摩弗拉斯身上取回奧術碎片，回大法師克希雷姆處覆命。", "法師職業任務。摩弗拉斯在副本內。", {{50,3}, {55,4}, {63,5}}, {20085}, "法師", 8379, "大法師克希雷姆", nil },
        { 8257, nil, 50, nil, "奧汀克", "艾薩拉 42,43", "亡靈的腐液", false, {8256}, nil, "前往沉沒的阿塔哈卡神廟殺死綠龍摩弗拉斯，把他的血液交給費伍德森林的格雷塔·苔蹄。", "牧師職業任務。摩弗拉斯在副本內。格雷塔·苔蹄(費伍德森林-翡翠聖地 51,82)。", {{50,3}, {55,4}, {63,5}}, {20025}, "牧師", 8405, "奧汀克", nil },
        { 8413, "H", 50, nil, "捕風者巴斯拉", "奧特蘭克山脈 80,67", "靈魂圖騰", false, {8412}, nil, "把巫毒羽毛交給捕風者巴斯拉。", "薩滿職業任務。6 個小巨魔每隻掉一根。", {{50,3}, {55,4}, {63,5}}, {20606, 20607, 20608}, "薩滿", 6176, "捕風者巴斯拉", nil },
        { 8418, nil, 50, nil, "阿什拉姆·瓦羅菲斯特", "西瘟疫之地 - 寒風營地 43,85", "惰性天災石", false, {8416}, nil, "把巫毒羽毛帶給阿什拉姆·瓦羅菲斯特。", "聖騎士職業任務。6 個小巨魔每隻掉一根。", {{50,3}, {55,4}, {63,5}}, {20606, 20607, 20608}, "聖騎士", 10838, "指揮官阿什拉姆·瓦羅菲斯特", nil },
        { 8422, nil, 50, nil, "伊普斯", "費伍德森林 42,45", "奇怪的材料", false, {8421}, nil, "到沉沒的神廟從巨魔身上收集 6 支巫毒羽毛。", "術士職業任務。6 個小巨魔每隻掉一根。", {{50,3}, {55,4}, {63,5}}, {20606, 20607, 20608}, "術士", 14470, "伊普斯", nil },
        { 8425, nil, 50, nil, "部落英雄的靈魂", "塵泥沼澤 34,66", "魔誓者之戰", false, {8424}, nil, "把從沉沒神廟巨魔身上得到的巫毒羽毛交給部落英雄的靈魂。", "戰士職業任務。6 個小巨魔就是守住迦瑪蘭結界的亡靈巨魔——進本上樓梯右轉那片（不是螺旋樓梯）。", {{50,3}, {55,4}, {63,5}}, {20606, 20607, 20608}, "戰士", 7572, "部落英雄的靈魂", nil },
        { 9053, nil, 50, nil, "托爾瓦·尋路者", "安戈洛環形山 72,76", "毒性測試", false, {9051}, nil, "從沉沒神廟底部的守衛身上取得一些腐爛藤蔓，交給托爾瓦·尋路者。", "德魯伊職業任務。藤蔓由召喚出的阿塔拉利恩掉落，需要先正確破解雕像群的祕密。雕像順序按小地圖鐘點：6 點 → 12 點 → 8 點 → 4 點 → 10 點 → 2 點（點對了雕像會亮綠燈）。", {{50,3}, {55,4}, {63,5}}, {22444}, "德魯伊", 9619, "托爾瓦·尋路者", nil },
    },
    ["blackrock_depths"] = {
        { 4083, nil, 40, 55, "塞娜尼·雷心", "黑石深淵", nil, true, nil, nil, "鬼魂之杯的塞娜尼·雷心要你找齊他要的材料。", "採礦 230 以上才能接；做完後學會熔煉黑鐵礦石。材料：2 個 [紅寶石]、20 個 [金錠]、10 個 [真銀錠]。之後帶 [黑鐵礦石] 到黑熔爐即可熔煉。", {{40,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {7910, 3577, 6037}, nil, nil, nil, { xp = 5650 } },
        { 3802, nil, 48, 52, "弗蘭克羅恩·鑄鐵", "黑石山 副本入口地圖", "黑鐵的遺產", false, {3801}, {11000}, "擊殺弗諾斯·達克維爾奪回戰錘「鐵膽」，再把鐵膽之錘放到索瑞森神殿弗蘭克羅恩·鑄鐵的雕像上。", "弗蘭克羅恩在黑石中心、自己墓穴的上方——需要先死亡變成鬼魂才能與他對話，對話兩次激活任務。弗諾斯·達克維爾在副本內，神殿在副本內。", {{48,2}, {50,3}, {55,4}, {63,5}}, {10999}, nil, 8888, "弗蘭克羅恩·鑄鐵", { xp = 5100, money = 23000 } },
        { 3906, "H", 48, nil, "桑德哈特", "荒蕪之地 - 卡加斯 3,48", nil, false, nil, nil, "到黑石山的採石場擊殺征服者派隆，回桑德哈特處彙報。", "派隆是副本入口外的一隻火元素精英。", {{48,2}, {50,3}, {55,4}, {63,5}}, nil, nil, 9084, "桑德哈特", nil },
        { 3907, "H", 48, 56, "桑德哈特", "荒蕪之地 - 卡加斯 3,48", "不和諧的烈焰", false, {3906}, {12113, 12114, 12112, 12115}, "進入黑石深淵找到並擊殺伊森迪奧斯，向桑德哈特彙報。", "前置從塞娜尼·雷心處接。伊森迪奧斯在副本內。", {{48,1}, {52,2}, {54,3}, {59,4}, {67,5}}, {11126}, nil, 9084, "桑德哈特", { xp = 7300, money = 25500, rep = { {81, 150, "雷霆崖"} } } },
        { 3981, "H", 48, nil, "神射手賈拉瑪弗", "荒蕪之地 - 卡加斯 5,47", "不和諧的烈焰", false, nil, nil, "進入黑石深淵找到指揮官哥沙克——草圖上畫着鐵欄後的獸人，去類似監獄的地方找。", "前置來自桑德哈特(荒蕪之地-卡加斯 3,48)；派隆就在副本入口前。哥沙克在副本內。監獄鑰匙由審訊官格斯塔恩掉落；與他對話開啓下一階段時會刷怪。", {{48,2}, {50,3}, {55,4}, {63,5}}, nil, nil, 9081, "神射手賈拉瑪弗", nil },
        { 4003, "H", 48, 59, "薩爾", "奧格瑞瑪 31,37", "東部王國", false, {4002}, nil, "擊殺達格蘭·索瑞森大帝，把鐵爐堡公主茉艾拉·銅須從詛咒中解救出來。", "先與卡蘭·巨錘和薩爾交談獲得任務。達格蘭在副本內。公主會治療達格蘭——千萬別殺公主，記得打斷她的治療！", {{48,1}, {55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 4949, "薩爾", { xp = 8050 } },
        { 4004, "H", 48, 60, "鐵爐堡公主茉艾拉·銅須", nil, nil, true, {4003}, {12544, 12545}, nil, nil, {{48,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 8929, "鐵爐堡公主茉艾拉·銅須", { xp = 9950, money = 27000, rep = { {67, 200, "部落"} } } },
        { 4081, "H", 48, 52, "通緝", "荒蕪之地 - 卡加斯 3,47", nil, false, nil, nil, "替軍官高圖斯清剿黑石深淵：15 個鐵怒衛士、10 個鐵怒獄卒、5 個鐵怒步兵，完成後回去覆命。", "這些矮人集中在黑石深淵前半段。高圖斯(荒蕪之地-卡加斯瞭望塔頂 5,47)。", {{48,2}, {50,3}, {55,4}, {63,5}}, nil, nil, nil, nil, { xp = 5100, money = 15500, rep = { {76, 100, "奧格瑞瑪"} } } },
        { 4136, nil, 48, 53, "尤卡·斯庫比格特", "燃燒平原 - 烈焰峯 65,22", "尤卡·斯庫比格特", false, {4324}, {11865, 11963, 12049}, "把雷布里的頭顱交給燃燒平原的尤卡·斯庫比格特。", "任務可直接接，前置從尤卡·斯庫比格特(塔納利斯-熱砂港 67,23)處接。雷布里在副本內。", {{48,1}, {49,2}, {51,3}, {56,4}, {64,5}}, {11313}, nil, 9544, "尤卡·斯庫比格特", { xp = 2650, money = 6000 } },
        { 4242, "A", 48, 54, "溫德索爾元帥", nil, "科林的烈酒", true, {4241}, {12018, 12021, 12041}, nil, "溫德索爾元帥被關在副本內的牢房裏（鑰匙由審訊官格斯塔恩掉落）。交完本任務沒有直接後續：回深淵繼續清怪，直到刷出「揉皺的便條」開啓下一段任務。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9023, "溫德索爾元帥", { xp = 5450, rep = { {72, 100, "暴風城"} } } },
        { 4262, "A", 48, nil, "加琳達", "燃燒平原 - 摩根的崗哨 85,69", nil, false, nil, nil, "擊殺征服者派隆，向加琳達覆命。", "派隆是副本入口外的火元素精英", {{48,2}, {50,3}, {55,4}, {63,5}}, nil, nil, 9561, "加琳達", nil },
        { 4263, "A", 48, 56, "加琳達", "燃燒平原 - 摩根的崗哨 85,69", "征服者派隆", false, {4262}, {12113, 12114, 12112, 12115}, "進入黑石深淵找到並擊殺伊森迪奧斯。", "前置在加琳達處接。伊森迪奧斯在副本內。", {{48,1}, {52,2}, {54,3}, {59,4}, {67,5}}, nil, nil, 9561, "加琳達", { xp = 5800, money = 8500, rep = { {54, 100, "諾莫瑞根流亡者"} } } },
        { 7201, "H", 48, 54, "暗法師薇薇安·拉格雷", "荒蕪之地 - 卡加斯 2,47", "不和諧的烈焰", false, {3906}, {12038}, "到黑石深淵收集 10 份元素精華——作戰傀儡、傀儡製造者身上找找，薇薇安·拉格雷還提到了元素生物……", "前置來自桑德哈特(荒蕪之地-卡加斯 3,48)；派隆就在副本入口前。所有元素生物都可能掉精華。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, {11129}, nil, 9078, "暗法師薇薇安·拉格雷", { xp = 5450, money = 24500, rep = { {68, 100, "幽暗城"} } } },
        { 4082, "H", 50, 54, "通緝", "荒蕪之地 - 卡加斯 3,47", "格殺勿論：黑鐵矮人", false, {4081}, nil, "替高圖斯軍閥清剿黑石深淵：10 個鐵怒醫師、10 個鐵怒士兵、10 個鐵怒軍官，完成後回去覆命。", "鐵怒矮人在貝爾加附近。高圖斯(荒蕪之地-卡加斯瞭望塔頂 5,47)；系列始於雷克斯洛特(荒蕪之地-卡加斯 5,47)。格拉克·洛克魯布(燃燒平原 38,35)：把他打到 50% 血以下並綁定後開始護送（精英）。", {{50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, nil, nil, { xp = 5450, money = 16500, rep = { {76, 100, "奧格瑞瑪"} } } },
        { 4123, nil, 50, 55, "麥克斯沃特·尤博格林", "燃燒平原 - 烈焰峯 65,23", nil, false, nil, nil, "把山脈之心交給燃燒平原的麥克斯沃特·尤博格林。", "山脈之心在黑色寶庫的寶箱裏。要先清完黑色寶庫的所有小寶箱、擊敗出現的 首領 才能拿到鑰匙。", {{50,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {11309}, nil, 9536, "麥克斯沃特·尤博格林", { xp = 5650, money = 8500 } },
        { 4126, "A", 50, 55, "拉格納·雷酒", "丹莫羅 - 卡拉諾斯 46,52", "拉格納·雷酒", false, {4128}, {11964, 12000, 12003}, "把遺失的雷酒祕方帶回卡拉諾斯交給拉格納·雷酒。", "前置來自恩諾哈爾·雷酒(詛咒之地-守望堡 61,18)。摧毀雷霆啤酒桶會刷出守衛，祕方在其中一名守衛身上。", {{50,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {11312}, nil, 1267, "拉格納·雷酒", { xp = 7050, money = 16500 } },
        { 4134, "H", 50, 55, "暗法師薇薇安·拉格雷", "荒蕪之地 - 卡加斯 2,47", "薇薇安·拉格雷", false, {4133}, {11964, 12000, 3928, 6149}, "把遺失的雷酒祕方交給卡加斯的薇薇安·拉格雷。", "前置由藥劑師金格給予(幽暗城-鍊金房 50,68)。砸破酒桶刷出的守衛中每名都掉祕方（全隊各拿各的）；團滅的話酒桶消失，需重置副本再來。", {{50,1}, {51,2}, {53,3}, {58,4}, {66,5}}, {11312}, nil, 9078, "暗法師薇薇安·拉格雷", { xp = 5650, money = 8500 } },
        { 4201, nil, 50, 54, "娜瑪拉小姐", "黑石深淵", nil, true, nil, {11962, 11866}, "把 4 份格羅姆之血、10 塊巨型銀礦和裝滿水的娜瑪拉之瓶交給黑石深淵的娜瑪拉小姐。", "巨型銀礦打艾薩拉的巨人；格羅姆之血可請草藥學玩家幫忙；瓶子(安戈洛環形山葛拉卡溫泉 31,50)裝水。交付後可直接走後門，不必再殺法拉克斯。", {{50,2}, {52,3}, {57,4}, {65,5}}, {8846, 11405, 11413, 11412}, nil, 9500, "娜瑪拉小姐", { xp = 5450, money = 8000 } },
        { 4264, "A", 50, 58, "由物品[揉皺的紙條]起始", nil, nil, false, nil, nil, nil, "「揉皺的便條」在深淵內隨機掉落。溫德索爾元帥在深淵的監獄裏——別搞混：麥克斯韋爾元帥在燃燒平原的摩根的崗哨。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {11446}, nil, nil, nil, { xp = 6200, rep = { {72, 100, "暴風城"} } } },
