        { 4286, "A", 50, 56, "奧拉留斯", "燃燒平原 - 摩根的崗哨 84,68", nil, false, nil, {11883}, "到黑石深淵找 20 個黑鐵挎包，回奧拉留斯處覆命。", "所有黑鐵矮人都可能掉挎包。", {{50,1}, {52,2}, {54,3}, {59,4}, {67,5}}, {11468}, nil, 9177, "奧拉留斯", { xp = 5800, money = 8500, rep = { {47, 100, "鐵爐堡"} } } },
        { 4322, "A", 50, 58, "溫德索爾元帥", nil, nil, true, nil, {12061, 12062, 12065}, nil, "越獄（護送溫德索爾）前確保全隊都已交掉前序任務，否則有人拿不到進度。完成後出本前必須先和溫德索爾對話，直接跑出副本就得重跑一遍。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 9023, "溫德索爾元帥", { xp = 7750, money = 17500, rep = { {72, 150, "暴風城"} } } },
        { 4341, "A", 50, nil, "國王麥格尼·銅須", "鐵爐堡 39,55", "索瑞森廢墟", false, {3701}, nil, "到黑石深淵找到卡蘭·巨錘——國王說他在那裏看守囚犯，去監獄附近找。", "前置始於皇家歷史學家阿克瑟努斯(鐵爐堡 38,55)。卡蘭·巨錘在副本內。", {{50,1}, {55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 2784, "國王麥格尼·銅須", nil },
        { 4362, "A", 50, 59, "國王麥格尼·銅須", "鐵爐堡 39,55", "糟糕的訊息", false, {4361}, nil, "重返黑石深淵，從達格蘭·索瑞森大帝手中救出鐵爐堡公主茉艾拉·銅須。", "公主在副本內。戰鬥中她會治療達格蘭，儘量打斷，但絕不能讓她死，否則任務失敗。救出後還要回鐵爐堡向麥格尼·銅須覆命。", {{50,1}, {55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 2784, "國王麥格尼·銅須", { xp = 8050, rep = { {47, 150, "鐵爐堡"} } } },
        { 4363, "A", 50, 59, "鐵爐堡公主茉艾拉·銅須", nil, nil, true, {4362}, {12548, 12543}, nil, nil, {{50,1}, {55,2}, {57,3}, {62,4}, {71,5}}, nil, nil, 8929, "鐵爐堡公主茉艾拉·銅須", { xp = 9650, money = 26500 } },
        { 4024, nil, 52, 58, "塞勒斯·薩雷芬圖斯", "燃燒平原 95,31", "烈焰精華", false, {4022}, {12066, 12082, 12083}, "進入黑石深淵擊殺貝爾加，用特殊黑龍皮從屍體上採集烈焰精華，交給塞勒斯·薩雷芬圖斯。", "系列始於卡拉然·溫佈雷(灼熱峽谷 39,38)。貝爾加在副本內。別忘了站在貝爾加屍體上使用背包裏的蛻皮物品，容易順手漏掉。", {{52,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {11230, 11231}, nil, 9459, "塞勒斯·薩雷芬圖斯", { xp = 6200, money = 26500 } },
        { 4063, "H", 52, 58, "魯特維爾·沃拉圖斯", "荒蕪之地 25,44", "機器的崛起", false, {4062}, {12109, 12110, 12108, 12111}, "擊殺傀儡統帥阿格曼奇並把頭交給魯特維爾，同時從護衛它的傀儡身上收集 10 塊完整的元素核心。", "前置來自聖者塞朵拉·穆瓦丹尼(荒蕪之地-卡加斯 3,47)。阿格曼奇在副本內。", {{52,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {11268, 11269}, nil, 2921, "魯特維爾·沃拉圖斯", { xp = 6200, money = 26500 } },
