        { 4132, "H", 52, 58, "軍官高圖斯", "荒蕪之地 - 卡加斯 5,47", "押送囚徒", false, {4121}, {12059}, "進入黑石深淵擊殺安格弗將軍，完成後向軍官高圖斯覆命。", "安格弗將軍在副本內。注意：他的生命低於 30% 時會召喚增援！", {{52,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 9077, "軍官高圖斯", { xp = 7750, money = 26500, rep = { {76, 150, "奧格瑞瑪"} } } },
        { 7848, nil, 55, nil, "洛索斯·天痕", "黑石山 副本入口地圖", nil, false, nil, nil, "進入黑石深淵，在通往熔火之心的傳送門附近找一塊熔火碎片，帶回黑石山交給洛索斯·天痕。", "完成後即可用洛索斯·天痕旁的傳送石直接進入熔火之心。熔火碎片在副本內。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18412}, nil, 14387, "洛索斯·天痕", nil },
        { 9015, nil, 58, 60, "法爾林·樹影", "厄運之槌 西，圖書館", "旗幟上的附魔", false, {8950}, nil, "前往黑石深淵競技場，在被裁決者格里斯通宣判時把挑釁旗幟插到中央；殺死瑟爾倫和他的戰士們，帶着第一塊瓦薩拉克護符回東瘟疫之地交給安希恩·哈莫。", "後續任務因職業而異。競技場事件：聽到喊話後把挑釁旗幟插在場地中央開打。◎ 寶箱必須由接任務的人第一個拾取，否則誰都拿不到飾品。", {{58,3}, {63,4}, {72,5}}, {22047, 21986}, nil, 16032, "法爾林·樹影", { xp = 6600 } },
        { 7604, nil, 60, 60, "羅克圖斯·暗契", "黑石深淵", nil, false, nil, {18592}, "如果願意接受薩弗隆的設計圖，就把瑟銀兄弟會契約交給羅克圖斯·暗契。", "籤契約需要薩弗隆鐵錠——熔火之心的焚化者古雷曼格掉落。", {{60,3}, {63,4}, {72,5}}, {18628, 17203}, nil, nil, nil, { xp = 6600, rep = { {59, 200, "瑟銀兄弟會"} } } },
        { 4241, "A", 75, nil, "科林的烈酒", "掉落自科林·烈酒", nil, false, {4224}, nil, "把科林的烈酒交給鐵爐堡附近美酒節營地的埃菲庫格·鐵桶。", "僅美酒節期間可接，任務物品每角色限取一次。埃菲庫格·鐵桶在美酒節營地(丹莫羅 47,39)。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9560, "麥克斯韋爾元帥", nil },
