    ["dire_maul_east"] = {
        { 7441, nil, 54, 58, "埃斯托爾迪", "菲拉斯 - 拉瑞斯小亭 76,37", nil, false, nil, {18411, 18410}, "到厄運之槌找到小鬼普希林，用任何手段拿回埃斯托爾迪的咒術之書。", "普希林在厄運之槌東；一對話就跑，追一段距離後它會停下並可以被攻擊。它還掉月牙鑰匙——厄運之槌北區和西區的門鑰匙。", {{54,2}, {56,3}, {61,4}, {69,5}}, {18261}, nil, 14355, "埃斯托爾迪", { xp = 7750, money = 17500, rep = { {809, 200, "辛德拉"} } } },
