        { 7489, "H", 54, 57, "塔羅·刺蹄", "菲拉斯 - 莫沙徹營地 76,43", "莫沙徹營地", false, {7492}, {18491}, "把蕾瑟塔蒂絲的網交給菲拉斯莫沙徹營地的塔羅·刺蹄。", "蕾瑟塔蒂絲在厄運之槌東。前置接自奧格瑞瑪的公告員高拉克。", {{54,2}, {55,3}, {60,4}, {68,5}}, {18426}, nil, 7776, "塔羅·刺蹄", { xp = 7550, money = 17000, rep = { {67, 150, "部落"} } } },
        { 7498, nil, 54, 60, "迦羅娜：潛行與詭計研究", "厄運之槌的所有幾個副本的 首領 都可能掉落", nil, false, nil, {18465}, "把這本典籍交給它的主人。", "盜賊職業飾品任務。交給博學者基爾達斯（厄運之槌西 - 圖書館）。", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18356}, "盜賊", nil, nil, { xp = 6600, rep = { {809, 200, "辛德拉"} } } },
