        { 5518, nil, 56, 60, "諾特·希姆加克", "厄運之槌 北，", nil, true, nil, {18258}, "把 4 卷符文布、8 塊硬甲皮、2 卷符文線和一份食人魔鞣酸交給被拴在厄運之槌戈多克食人魔區的諾特·希姆加克。", "可重複任務。食人魔鞣酸在副本上層附近獲取。", {{56,2}, {58,3}, {63,4}, {72,5}}, {14048, 8170, 14341, 18240}, nil, 14338, "諾特·希姆加克", { xp = 6600, rep = { {169, 100, "熱砂港"} } } },
