        { 7503, nil, 54, 60, "最偉大的獵手", "厄運之槌的所有幾個副本的 首領 都可能掉落", nil, false, nil, {18473}, "把這本典籍交給它的主人。", "獵人職業飾品任務。交給博學者麥庫斯（厄運之槌西 - 圖書館）。", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18361}, "獵人", nil, nil, { xp = 6600, rep = { {809, 200, "辛德拉"} } } },
        { 7504, nil, 54, 60, "光明不會告訴你的事情", "厄運之槌的所有幾個副本的 首領 都可能掉落", nil, false, nil, {18469}, "把這本典籍交給它的主人。", "牧師職業飾品任務。交給博學者亞沃（厄運之槌西 - 圖書館）。", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18362}, "牧師", nil, nil, { xp = 6600, rep = { {809, 200, "辛德拉"} } } },
