        { 7506, nil, 54, 60, "翡翠夢境", "厄運之槌的所有幾個副本的 首領 都可能掉落", nil, false, nil, {18470}, "把這本典籍交給它的主人。", "德魯伊職業飾品任務。交給博學者亞沃（厄運之槌西 - 圖書館）。", {{54,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18364}, "德魯伊", nil, nil, { xp = 6600, money = 100, rep = { {809, 200, "辛德拉"} } } },
        { 1318, nil, 56, 60, nil, nil, nil, false, nil, {18366, 18367, 18368, 18369}, nil, "可一趟連做，推薦路線：先北（貢品，備好食人魔套裝材料與壞陷阱）→ 西（殺伊莫塔爾）→ 圖書館（殺托塞德林王子）→ 回北出門時向芬古斯交任務。", {{56,2}, {58,3}, {63,4}, {72,5}}, {18336}, nil, nil, nil, { xp = 8300 } },
        { 7461, nil, 56, 60, "辛德拉古靈", "厄運之槌 西，（上層）", nil, true, nil, nil, "擊破維持伊莫塔爾監獄的五座水晶塔周圍的守衛，削弱水晶塔能量讓力場消散；進監獄殺掉中間的惡魔；最後在圖書館挑戰托塞德林王子。完成後到庭院找辛德拉古靈。", "水晶塔、伊莫塔爾、托塞德林王子都在副本內，水晶塔要先關閉", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, "辛德拉古靈", { xp = 9950 } },
        { 7462, "A", 56, 60, "辛德拉古靈", nil, nil, true, {7461}, {18420, 18421, 18424}, nil, nil, {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, nil, nil, { xp = 660, money = 27000 } },
        { 7877, nil, 56, 60, "辛德拉古靈", "厄運之槌 西，（上層）", "伊莫塔爾的瘋狂", true, {7461}, {18420, 18421, 18424}, "回圖書館找到辛德拉的寶藏，領取你的獎勵吧！", "寶藏就在圖書館的梯子下面。", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14358, "辛德拉古靈", { xp = 660, money = 27000 } },
        { 5528, nil, 57, 60, "踐踏者克雷格", "厄運之槌 北，", nil, true, nil, {18269, 18284}, "獲取免費的酒。", "和克雷格對話即可同時接取並交付；注意要帶着《當國王真好》這個狀態。", {{56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 14322, "踐踏者克雷格", nil },
        { 8948, nil, 58, 60, "安泰恩·哈爾蒙", "東瘟疫之地", "安泰恩的奇怪請求", false, {8947}, nil, nil, nil, {{58,3}, {63,4}, {72,5}}, {21983}, nil, 16016, "安泰恩·哈爾蒙", { xp = 6600 } },
        { 8949, nil, 58, 60, "法爾林·樹影", nil, nil, true, {8948}, {22150, 22149}, nil, "戰珠掉率：厄運之槌北約 1/10、黑下約 1/7（但黑下食人魔數量少得多）、厄運競技場外約 1/50。", {{58,3}, {63,4}, {72,5}}, {21982}, nil, 16032, "法爾林·樹影", { xp = 6600 } },
        { 8950, nil, 58, 60, "法爾林·樹影", nil, nil, true, {8949}, nil, nil, "暗影精華出自厄運之槌西的幽靈怪。", {{58,3}, {63,4}, {72,5}}, {22224, 20520, 14344}, nil, 16032, "法爾林·樹影", { xp = 6600 } },
        { 8967, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖[D]", "重要的材料", false, {8963}, nil, "用召喚火盆召出伊薩利恩的靈魂並殺掉她，把火盆和瓦塔拉克飾品左瓣還給伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。伊薩利恩在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {21984, 22050}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8990, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖[D]", "更多重要的材料", false, {8985}, nil, "用召喚火盆召出伊薩莉恩的靈魂並殺掉他，把火盆和瓦塔拉克公爵的飾品還給伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。伊薩莉恩在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {22048, 22050}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 7507, nil, 60, 60, "博學者萊德羅斯", "厄運之槌 西，圖書館", nil, false, nil, nil, "把急速聖典、1 塊原始黑鑽石、2 份大塊魔光碎片和 2 份英雄之血交給厄運之槌的博學者萊德羅斯，換取一份急速祕藥。", "無前置，但精靈的傳說任務要先完成才能接。聖典隨機掉落、可交易。英雄之血在東西瘟疫之地地面隨機刷新，拾取綁定。", {{60,3}, {63,4}, {72,5}}, {18401}, nil, nil, nil, { xp = 9950, rep = { {809, 200, "辛德拉"} } } },
        { 7508, nil, 60, 60, "由物品[又鈍又平的精靈之刃]起始", nil, nil, false, {7507}, nil, nil, "《屠龍綱要》（厄運之槌掉落、可交易）觸發奎爾塞拉任務鏈：把書交給厄運之槌西圖書館的博學者，換取「又鈍又平的精靈之刃」開始這段史詩武器任務。", {{60,3}, {63,4}, {72,5}}, {18513}, nil, nil, nil, { xp = 9950 } },
        { 7631, nil, 60, nil, "莫蘇爾", "燃燒平原 12,31", "瓶中的小鬼（術士任務）", false, {7629}, nil, "閱讀莫蘇爾的指南，召喚克索諾斯恐懼戰馬，擊敗它並控制它的靈魂。", "術士史詩戰馬的最後一步：先關閉水晶塔、殺掉伊莫塔爾，然後才能召喚。備好 20 個以上靈魂碎片——維持法陣要持續消耗。殺掉戰馬後與馬的靈魂對話完成任務。", {{60,3}, {4,4}, {6,5}}, {18818}, "術士", 14436, "莫蘇爾·召血者", nil },
