    ["scholomance"] = {
        { 5341, "H", 52, 60, "阿萊克斯·巴羅夫", "提瑞斯法林地 - 亡靈壁壘 80,73", nil, false, nil, nil, "到通靈學院取回巴羅夫家族的四份地契（凱爾達隆、布瑞爾、塔倫米爾、南海鎮），交回阿萊克斯·巴羅夫。", "地契位置：凱爾達隆在進門後的第一間大廳；南海鎮=過橋後第一間大廳左角書桌上；塔倫米爾=幼龍房前房間的右角書桌；布瑞爾=萊斯·霜語所在的房間。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13471, 13448, 13450, 13451}, nil, 11022, "阿萊克斯·巴羅夫", { xp = 6600, money = 18000 } },
        { 5343, "A", 52, 60, "維爾頓·巴羅夫", "西瘟疫之地 - 寒風營地 43,83", nil, false, nil, nil, "到通靈學院取回巴羅夫家族的四份地契（凱爾達隆、布瑞爾、塔倫米爾、南海鎮），交回維爾頓·巴羅夫。", "地契位置：凱爾達隆在進門後的第一間大廳；南海鎮=過橋後第一間大廳左角書桌上；塔倫米爾=幼龍房前房間的右角書桌；布瑞爾=萊斯·霜語所在的房間。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13471, 13448, 13450, 13451}, nil, 11023, "維爾頓·巴羅夫", { xp = 6600, money = 18000 } },
        { 5382, nil, 55, 60, "艾瓦·薩克霍夫", "西瘟疫之地 - 凱爾達隆 70,73", nil, false, nil, nil, "在通靈學院找到瑟爾林·卡斯迪諾夫教授，殺掉他並燒燬艾瓦·薩克霍夫與盧森·薩克霍夫的遺體，然後回艾瓦·薩克霍夫處覆命。", "教授死後看房間兩側的肉堆——伊娃·薩克霍夫夫婦的遺骸就在裏面，清掉即完成。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11216, "艾瓦·薩克霍夫", { xp = 6600 } },
        { 5384, nil, 55, 60, "艾瓦·薩克霍夫", "西瘟疫之地 - 凱爾達隆 70,73", "卡斯迪諾夫的恐懼之袋", false, {5515}, {15805, 15806, 13544}, "帶無辜者之血回通靈學院，倒在門廊火盆下引出基爾圖諾斯；勇敢迎戰，別退縮。殺死他後回艾瓦·薩克霍夫處覆命。", "門廊在副本內。無辜者之血在第一間房的魅魔身上 100% 掉落；若召喚的克爾托諾斯沒開出想要的獎勵，可放棄重接（需重置副本重新召喚）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13523}, nil, 11216, "艾瓦·薩克霍夫", { xp = 8300 } },
        { 5515, nil, 55, 60, "艾瓦·薩克霍夫", "西瘟疫之地 - 凱爾達隆 70,73", "瑟爾林·卡斯迪諾夫教授", false, {5382}, nil, "在通靈學院擊敗詹迪斯·巴羅夫，從屍體上取得卡斯迪諾夫的恐懼之袋，交給艾瓦·薩克霍夫。", "詹迪斯·巴羅夫在副本內。分身只有本體有血條——開血條顯示（V 鍵）或給本體上標記，只打有血條的那個。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13725}, nil, 11216, "艾瓦·薩克霍夫", { xp = 6600 } },
        { 5529, nil, 55, 58, "貝蒂娜·比格辛克", "東瘟疫之地 - 聖光之願禮拜堂 76,54", nil, false, nil, nil, "擊殺 20 只瘟疫龍崽，回聖光之願禮拜堂向貝蒂娜·比格辛克覆命。", "瘟疫龍崽在屍骨儲藏所——去往血骨傀儡的大房間那片。", {{55,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 11035, "貝蒂娜·比格辛克", { xp = 6200, money = 9000, rep = { {529, 100, "銀色黎明"} } } },
        { 5582, nil, 55, nil, "健康的龍鱗", "通靈學院瘟疫龍崽隨機掉落", "瘟疫之龍", false, {5529}, nil, "把健康的龍鱗交給東瘟疫之地聖光之願禮拜堂的貝蒂娜·比格辛克。", "要先完成《瘟疫龍崽》纔會出現可採的健康龍鱗（否則看不見）。健康的龍鱗由瘟疫龍崽掉落（約 8%）。貝蒂娜·比格辛克(東瘟疫之地-聖光之願禮拜堂 76,54)。", {{55,2}, {56,3}, {61,4}, {69,5}}, {13920}, nil, nil, nil, nil },
        { 4771, nil, 57, 60, "貝蒂娜·比格辛克", "東瘟疫之地 - 聖光之願禮拜堂 77,54", "貝蒂娜·比格辛克", false, {5531}, {15853, 15854}, "把黎明先鋒放到通靈學院的觀察室，擊敗維克圖斯後回貝蒂娜·比格辛克處覆命。", "前置《雛龍精華》始於丁奇·斯迪波爾(燃燒平原-烈焰峯 65,23)。觀察室在副本內。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12368}, nil, 11035, "貝蒂娜·比格辛克", { xp = 9950, money = 27000, rep = { {529, 200, "銀色黎明"} } } },
        { 5466, nil, 57, 60, "馬杜克鎮長", "西瘟疫之地 - 凱爾達隆 70,73", "禁錮靈魂的遺物", false, {5465}, {13982, 13986, 13984, 14002}, "在通靈學院找到萊斯·霜語，用禁錮靈魂的遺物破除他的亡靈外殼，成功後殺掉他，把頭顱交給馬杜克鎮長。", "萊斯·霜語在副本內。", {{57,2}, {58,3}, {63,4}, {72,5}}, {13626, 13752}, nil, 11286, "馬杜克鎮長", { xp = 9950 } },
        { 5531, nil, 57, 60, "萊尼德·巴薩羅梅", "東瘟疫之地", "萊尼德·巴薩羅梅", false, {5522}, nil, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {13761}, nil, 11036, "萊尼德·巴薩羅梅", { xp = 1650, rep = { {529, 25, "銀色黎明"} } } },
        { 8258, "H", 58, nil, "薩格尼", "奧格瑞瑪 - 智慧谷 38.6, 36.2", "收集材料", false, {7667}, nil, "在通靈學院地下室的屍骨儲藏所中心使用預言水晶球，擊敗召喚出的幽靈；死亡騎士達克雷爾現身後再擊敗他，把頭顱交給奧格瑞瑪智慧谷的薩格尼。", "薩滿祭司專屬任務，前置接自同一 NPC。達克雷爾在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {18880, 18746}, "薩滿", nil, nil, nil },
        { 8969, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖[D]", "重要的材料", false, {8965}, nil, "用召喚火盆召出庫爾莫克的靈魂並殺掉他，把火盆和瓦塔拉克飾品左瓣還給黑石山的伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。庫爾莫克在副本內。", {{58,3}, {63,4}, {72,5}}, {21984, 22052}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8992, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖[D]", "更多重要的材料", false, {8988}, nil, "用召喚火盆召出庫爾莫克的靈魂並殺掉他，把火盆和瓦塔拉克公爵的飾品還給黑石山的伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。庫爾莫克在副本內。", {{58,3}, {63,4}, {72,5}}, {22048, 22052}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 7629, nil, 60, nil, "戈瑟奇·邪眼", "燃燒平原 12,31", "克索諾斯星塵", false, {7625}, nil, "把瓶中的小鬼帶到通靈學院的鍊金實驗室，等它造出羊皮紙後把瓶子還給戈瑟奇·邪眼。", "僅術士可接！鍊金實驗室就在萊斯·霜語所在的房間裏。", {{60,3}, {4,4}, {6,5}}, {18688}, "術士", 14437, "戈瑟奇·邪眼", nil },
        { 7647, nil, nil, nil, nil, nil, nil, false, {7646}, nil, nil, nil, {{60,3}, {4,4}, {6,5}}, {18799, 18792, 18804}, "聖騎士", 928, "格雷森·沙東布瑞克公爵", nil },
    },
    ["stratholme_main"] = {
        { 5305, nil, 50, nil, "輕盈的莉莉絲", "冬泉谷 - 永望鎮 61,37", nil, false, nil, nil, "到斯坦索姆殺死紅衣鑄錘師，把他的圍裙交給莉莉絲。", "紅衣鑄錘師靠召喚出現：點擊地上的「鍛造計劃書」羊皮紙觸發。", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13351}, nil, 11191, "輕盈的莉莉絲", nil },
        { 5307, nil, 50, nil, "亡靈殺手瑟里爾", "冬泉谷 - 永望鎮 61,37", nil, false, nil, nil, "在斯坦索姆找到黑衣守衛鑄劍師並殺掉，把黑色衛士徽記交給亡靈殺手瑟里爾。", "黑衣守衛鑄劍師靠召喚出現：點擊安娜絲塔麗之塔旁當鋪邊地上的「鍛造計劃書」觸發。", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13350}, nil, 11193, "亡靈殺手瑟里爾", nil },
        { 5848, nil, 52, 60, "畫家瑞弗蕾", "西瘟疫之地 - 凱爾達隆 65,75", "愛與家庭", false, {5846}, nil, "到斯坦索姆的血色十字軍堡壘找回名畫《愛與家庭》——它藏在另一幅雙月之畫的後面——把畫歸還給提里奧·弗丁。", "前置從提里奧·弗丁處接(西瘟疫之地 7,43)。畫在活人區檔案室進門右手邊。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {14679}, nil, 11936, "畫家瑞弗蕾", { xp = 6600 } },
        { 5125, nil, 55, 60, "奧裏克斯", "斯坦索姆", "信仰獎章", true, {"信仰獎章"}, {17044, 17045}, "擊殺瑞文戴爾男爵。", "先給奧裏克斯 [信仰獎章]（獎章在副本內的瑪洛爾保險箱裏）；他會加入對抗男爵的戰鬥但會倒下。殺死男爵後與屍體對話完成任務。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10917, "奧裏克斯", { xp = 9950 } },
        { 5212, nil, 55, nil, "貝蒂娜·比格辛克", "東瘟疫之地 - 聖光之願禮拜堂 76,54", nil, false, nil, nil, "從斯坦索姆找回 20 個瘟疫肉塊，交給貝蒂娜·比格辛克。", "斯坦索姆大部分敵人都會掉肉塊，但掉率偏低。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13174}, nil, 11035, "貝蒂娜·比格辛克", { xp = 6600, money = 18000, rep = { {529, 100, "銀色黎明"} } } },
        { 5213, nil, 55, 60, "貝蒂娜·比格辛克", "東瘟疫之地 - 聖光之願禮拜堂 76,54", "血肉不會撒謊", false, {5212}, {13209, 19812}, "到斯坦索姆探索通靈塔，找到新的天災軍團檔案交給貝蒂娜·比格辛克。", "檔案小盒隨機刷在奈魯布恩坎、安娜絲塔麗、馬勒基三座通靈塔中的一座裏；盒子不會消失，全隊每人都拿得到。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13176}, nil, 11035, "貝蒂娜·比格辛克", { xp = 6600, rep = { {529, 100, "銀色黎明"} } } },
        { 5214, nil, 55, 60, "煙鬼拉魯恩", "東瘟疫之地 - 聖光之願禮拜堂 75,52", nil, false, nil, {13171}, "在斯坦索姆找到弗拉斯·希亞比的菸草店，取回一盒希亞比的菸草交給煙鬼拉魯恩。", "菸草店在副本內：一路左轉到底的死角、水井右側，需清完沿途；開盒的瞬間弗拉斯·希亞比會現身。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13172}, nil, 11033, "煙鬼拉魯恩", { xp = 8300 } },
        { 5243, nil, 55, 60, "萊尼德·巴薩羅梅", "東瘟疫之地 - 聖光之願禮拜堂 76,52", nil, false, nil, {13216, 13217, 3928, 6149}, "前往斯坦索姆，搜刮城中散落的補給箱，收集 5 瓶斯坦索姆聖水，回萊尼德·巴薩羅梅處覆命。", "聖水在城中各處的箱子裏；部分是假箱，打開會鑽出一堆蟲子。矮人用「尋寶」能在小地圖上標出真箱子。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13180}, nil, 11036, "萊尼德·巴薩羅梅", { xp = 6600, money = 18000, rep = { {529, 100, "銀色黎明"} } } },
        { 5251, nil, 55, 60, "尼古拉斯·瑟倫霍夫公爵", "東瘟疫之地 - 聖光之願禮拜堂 76,52", nil, false, nil, nil, "在斯坦索姆找到血色十字軍的檔案管理員加爾福特，殺掉並燒燬血色十字軍檔案。", "檔案與檔案管理員都在副本內。◎ 若同時在做《愛與家庭》：燒檔案前先拿到畫——畫和檔案會被一起燒掉。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11039, "尼古拉斯·瑟倫霍夫公爵", { xp = 8300, money = 18000, rep = { {529, 150, "銀色黎明"} } } },
        { 5262, nil, 55, 60, "巴納扎爾", "斯坦索姆", "檔案管理員", false, nil, nil, "把巴納扎爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。", "公爵(東瘟疫之地-聖光之願禮拜堂 76,52)。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13250}, nil, nil, nil, { xp = 8300, rep = { {529, 150, "銀色黎明"} } } },
        { 5263, nil, 55, nil, "尼古拉斯·瑟倫霍夫公爵", "東瘟疫之地 - 聖光之願禮拜堂 76,52", "可怕的真相", false, {5262}, nil, "到斯坦索姆擊殺瑞文戴爾男爵，把頭顱交給尼古拉斯·瑟倫霍夫公爵。", "男爵在副本內。此任務有後續任務給獎勵。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13251}, nil, 11039, "尼古拉斯·瑟倫霍夫公爵", { xp = 8300, rep = { {529, 150, "銀色黎明"} } } },
        { 5282, nil, 55, 60, "埃根", "東瘟疫之地 11,29", "永不安息的靈魂", false, {5281}, {13315}, "對斯坦索姆的鬼魂居民使用埃根的衝擊器；靈魂脫離軀殼後再用一次，讓它們徹底安息。解放 15 個永不安息的靈魂後回埃根處覆命。", "前置從護理者奧林處接(東瘟疫之地-聖光之願禮拜堂 74,58)。鬼魂居民在城中到處遊蕩。衝擊槍打中鬼魂約 10 秒後其身邊會出現「不安的靈魂」，對它再補一槍即可拾取。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13289}, nil, 11140, "埃根", { xp = 8300, money = 18000 } },
        { 6163, "H", 56, nil, "納薩諾斯·凋零者", "東瘟疫之地 22,68", "暗翼蝠", false, {6135}, nil, "到斯坦索姆擊殺吞嚥者拉姆斯登，把頭顱交給納薩諾斯。", "前置同樣在納薩諾斯處接。拉姆斯登在副本內。", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "納薩諾斯·凋零者", { xp = 6600, money = 18000, rep = { {68, 100, "幽暗城"} } } },
        { 5463, nil, 57, 60, "萊尼德·巴薩羅梅", "東瘟疫之地 - 聖光之願禮拜堂 75,52", "亡靈萊斯·霜語", false, {5462}, nil, "到斯坦索姆找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。", "前置從馬杜克鎮長處接(西瘟疫之地-凱爾達隆 70,73)。標記就是男爵房間地上的五芒星。另見通靈學院的「巫妖萊斯·霜語」。", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "萊尼德·巴薩羅梅", { xp = 6600 } },
        { 8945, nil, 58, 60, "伊思達·哈爾蒙", "東瘟疫之地 - 斯坦索姆", "尋找安泰恩", false, {8929}, {22137}, "進入斯坦索姆，從瑞文戴爾男爵手中救出伊思達。", "伊思達·哈爾蒙就站在副本門口，需要超維度幽靈顯形器才能看到他。前置：聯盟找德莉亞娜(鐵爐堡 43,52)，部落找莫克瓦爾(奧格瑞瑪 38,37)。這也是著名的「45 分鐘瑞文戴爾」任務。", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "安泰恩·哈爾蒙", { xp = 8300 } },
        { 8968, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖中的[D]", "重要的材料", false, {8964}, nil, "用召喚火盆召出亞雷恩和索托斯的靈魂並殺掉他們，把火盆和瓦塔拉克飾品左瓣還給黑石山的伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。兩人在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8991, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖中的[D]", "更多重要的材料", false, {8987}, nil, "用召喚火盆召出亞雷恩和索托斯的靈魂並殺掉他們，把火盆和瓦塔拉克公爵的飾品還給黑石山的伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。兩人在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 7622, nil, 60, nil, "艾瑞斯·哈文法", "東瘟疫之地 17,14", "警示", false, {7621}, nil, "在 15 個農夫被殺之前拯救 50 個農夫，完成後與艾瑞斯·哈文法談談。拯救進度可以看死亡佈告。", "見到艾瑞斯·哈文法並接任務需要神聖之眼（火焰之王的寶箱，熔火之心出）。完成後把神聖之眼、諾達希爾碎片和暗影之眼（詛咒之地/冬泉谷隨機惡魔掉落）組合，得到牧師史詩法杖——祈福。", {{60,3}, {63,4}, {72,5}}, nil, "牧師", 14494, "艾瑞斯·哈文法", nil },
        { 9257, nil, 60, nil, "阿納克洛斯", "塔納利斯 - 時光之穴 65,49", "埃提耶什，被玷污的傳說之杖", false, {9251}, nil, "塔納利斯時光之穴的阿納克洛斯要你前往斯坦索姆，在神聖之地上使用埃提耶什、守護者的傳說之杖，擊敗被驅趕出來的生物後回他那裏覆命。", "召喚位置在副本內。巫妖王之怒資料片中無法再獲得此任務；只有「召喚出埃提耶什」這一步仍可完成。", {{60,3}, {63,4}, {72,5}}, {22737}, "牧師", nil, nil, nil },
    },
    ["stratholme_service"] = {
        { 5305, nil, 50, nil, "輕盈的莉莉絲", "冬泉谷 - 永望鎮 61,37", nil, false, nil, nil, "到斯坦索姆殺死紅衣鑄錘師，把他的圍裙交給莉莉絲。", "紅衣鑄錘師靠召喚出現：點擊地上的「鍛造計劃書」羊皮紙觸發。", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13351}, nil, 11191, "輕盈的莉莉絲", nil },
        { 5307, nil, 50, nil, "亡靈殺手瑟里爾", "冬泉谷 - 永望鎮 61,37", nil, false, nil, nil, "在斯坦索姆找到黑衣守衛鑄劍師並殺掉，把黑色衛士徽記交給亡靈殺手瑟里爾。", "黑衣守衛鑄劍師靠召喚出現：點擊安娜絲塔麗之塔旁當鋪邊地上的「鍛造計劃書」觸發。", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13350}, nil, 11193, "亡靈殺手瑟里爾", nil },
        { 5848, nil, 52, 60, "畫家瑞弗蕾", "西瘟疫之地 - 凱爾達隆 65,75", "愛與家庭", false, {5846}, nil, "到斯坦索姆的血色十字軍堡壘找回名畫《愛與家庭》——它藏在另一幅雙月之畫的後面——把畫歸還給提里奧·弗丁。", "前置從提里奧·弗丁處接(西瘟疫之地 7,43)。畫在活人區檔案室進門右手邊。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {14679}, nil, 11936, "畫家瑞弗蕾", { xp = 6600 } },
        { 5125, nil, 55, 60, "奧裏克斯", "斯坦索姆", "信仰獎章", true, {"信仰獎章"}, {17044, 17045}, "擊殺瑞文戴爾男爵。", "先給奧裏克斯 [信仰獎章]（獎章在副本內的瑪洛爾保險箱裏）；他會加入對抗男爵的戰鬥但會倒下。殺死男爵後與屍體對話完成任務。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10917, "奧裏克斯", { xp = 9950 } },
        { 5212, nil, 55, 60, "貝蒂娜·比格辛克", "東瘟疫之地 - 聖光之願禮拜堂 76,54", nil, false, nil, nil, "從斯坦索姆找回 20 個瘟疫肉塊，交給貝蒂娜·比格辛克。", "斯坦索姆大部分敵人都會掉肉塊，但掉率偏低。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13174}, nil, 11035, "貝蒂娜·比格辛克", { xp = 6600, money = 18000, rep = { {529, 100, "銀色黎明"} } } },
        { 5213, nil, 55, 60, "貝蒂娜·比格辛克", "東瘟疫之地 - 聖光之願禮拜堂 76,54", "血肉不會撒謊", false, {5212}, {13209, 19812}, "到斯坦索姆探索通靈塔，找到新的天災軍團檔案交給貝蒂娜·比格辛克。", "檔案小盒隨機刷在奈魯布恩坎、安娜絲塔麗、馬勒基三座通靈塔中的一座裏；盒子不會消失，全隊每人都拿得到。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13176}, nil, 11035, "貝蒂娜·比格辛克", { xp = 6600, rep = { {529, 100, "銀色黎明"} } } },
        { 5214, nil, 55, 60, "煙鬼拉魯恩", "東瘟疫之地 - 聖光之願禮拜堂 75,52", nil, false, nil, {13171}, "在斯坦索姆找到弗拉斯·希亞比的菸草店，取回一盒希亞比的菸草交給煙鬼拉魯恩。", "菸草店在副本內：一路左轉到底的死角、水井右側，需清完沿途；開盒的瞬間弗拉斯·希亞比會現身。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13172}, nil, 11033, "煙鬼拉魯恩", { xp = 8300 } },
        { 5243, nil, 55, 60, "萊尼德·巴薩羅梅", "東瘟疫之地 - 聖光之願禮拜堂 76,52", nil, false, nil, {13216, 13217, 3928, 6149}, "前往斯坦索姆，搜刮城中散落的補給箱，收集 5 瓶斯坦索姆聖水，回萊尼德·巴薩羅梅處覆命。", "聖水在城中各處的箱子裏；部分是假箱，打開會鑽出一堆蟲子。矮人用「尋寶」能在小地圖上標出真箱子。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13180}, nil, 11036, "萊尼德·巴薩羅梅", { xp = 6600, money = 18000, rep = { {529, 100, "銀色黎明"} } } },
        { 5251, nil, 55, nil, "尼古拉斯·瑟倫霍夫公爵", "東瘟疫之地 - 聖光之願禮拜堂 76,52", nil, false, nil, nil, "在斯坦索姆找到血色十字軍的檔案管理員加爾福特，殺掉並燒燬血色十字軍檔案。", "檔案與檔案管理員都在副本內。◎ 若同時在做《愛與家庭》：燒檔案前先拿到畫——畫和檔案會被一起燒掉。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11039, "尼古拉斯·瑟倫霍夫公爵", { xp = 8300, money = 18000, rep = { {529, 150, "銀色黎明"} } } },
        { 5262, nil, 55, nil, "巴納扎爾", "斯坦索姆", "檔案管理員", false, nil, nil, "把巴納扎爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。", "公爵(東瘟疫之地-聖光之願禮拜堂 76,52)。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13250}, nil, nil, nil, { xp = 8300, rep = { {529, 150, "銀色黎明"} } } },
        { 5263, nil, 55, 60, "尼古拉斯·瑟倫霍夫公爵", "東瘟疫之地 - 聖光之願禮拜堂 76,52", "可怕的真相", false, {5262}, nil, "到斯坦索姆擊殺瑞文戴爾男爵，把頭顱交給尼古拉斯·瑟倫霍夫公爵。", "男爵在副本內。此任務有後續任務給獎勵。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13251}, nil, 11039, "尼古拉斯·瑟倫霍夫公爵", { xp = 8300, rep = { {529, 150, "銀色黎明"} } } },
        { 5282, nil, 55, 60, "埃根", "東瘟疫之地 11,29", "永不安息的靈魂", false, {5281}, {13315}, "對斯坦索姆的鬼魂居民使用埃根的衝擊器；靈魂脫離軀殼後再用一次，讓它們徹底安息。解放 15 個永不安息的靈魂後回埃根處覆命。", "前置從護理者奧林處接(東瘟疫之地-聖光之願禮拜堂 74,58)。鬼魂居民在城中到處遊蕩。衝擊槍打中鬼魂約 10 秒後其身邊會出現「不安的靈魂」，對它再補一槍即可拾取。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13289}, nil, 11140, "埃根", { xp = 8300, money = 18000 } },
        { 6163, "H", 56, 60, "納薩諾斯·凋零者", "東瘟疫之地 22,68", "暗翼蝠", false, {6135}, {18022, 17001}, "到斯坦索姆擊殺吞嚥者拉姆斯登，把頭顱交給納薩諾斯。", "前置同樣在納薩諾斯處接。拉姆斯登在副本內。", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "納薩諾斯·凋零者", { xp = 6600, money = 18000, rep = { {68, 100, "幽暗城"} } } },
        { 5463, nil, 57, 60, "萊尼德·巴薩羅梅", "東瘟疫之地 - 聖光之願禮拜堂 75,52", "亡靈萊斯·霜語", false, {5462}, nil, "到斯坦索姆找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。", "前置從馬杜克鎮長處接(西瘟疫之地-凱爾達隆 70,73)。標記就是男爵房間地上的五芒星。另見通靈學院的「巫妖萊斯·霜語」。", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "萊尼德·巴薩羅梅", { xp = 6600 } },
        { 8945, nil, 58, 60, "伊思達·哈爾蒙", "東瘟疫之地 - 斯坦索姆", "尋找安泰恩", false, {8929}, {22137}, "進入斯坦索姆，從瑞文戴爾男爵手中救出伊思達。", "伊思達·哈爾蒙就站在副本門口，需要超維度幽靈顯形器才能看到他。前置：聯盟找德莉亞娜(鐵爐堡 43,52)，部落找莫克瓦爾(奧格瑞瑪 38,37)。這也是著名的「45 分鐘瑞文戴爾」任務。", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "安泰恩·哈爾蒙", { xp = 8300 } },
        { 8968, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖中的[D]", "重要的材料", false, {8964}, nil, "用召喚火盆召出亞雷恩和索托斯的靈魂並殺掉他們，把火盆和瓦塔拉克飾品左瓣還給黑石山的伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。兩人在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8991, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖中的[D]", "更多重要的材料", false, {8987}, nil, "用召喚火盆召出亞雷恩和索托斯的靈魂並殺掉他們，把火盆和瓦塔拉克公爵的飾品還給黑石山的伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。兩人在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 7622, nil, 60, nil, "艾瑞斯·哈文法", "東瘟疫之地 17,14", "警示", false, {7621}, nil, "在 15 個農夫被殺之前拯救 50 個農夫，完成後與艾瑞斯·哈文法談談。拯救進度可以看死亡佈告。", "見到艾瑞斯·哈文法並接任務需要神聖之眼（火焰之王的寶箱，熔火之心出）。完成後把神聖之眼、諾達希爾碎片和暗影之眼（詛咒之地/冬泉谷隨機惡魔掉落）組合，得到牧師史詩法杖——祈福。", {{60,3}, {63,4}, {72,5}}, nil, "牧師", 14494, "艾瑞斯·哈文法", nil },
        { 9257, nil, 60, nil, "阿納克洛斯", "塔納利斯 - 時光之穴 65,49", "埃提耶什，被玷污的傳說之杖", false, {9251}, nil, "塔納利斯時光之穴的阿納克洛斯要你前往斯坦索姆，在神聖之地上使用埃提耶什、守護者的傳說之杖，擊敗被驅趕出來的生物後回他那裏覆命。", "召喚位置在副本內。巫妖王之怒資料片中無法再獲得此任務；只有「召喚出埃提耶什」這一步仍可完成。", {{60,3}, {63,4}, {72,5}}, {22737}, "牧師", nil, nil, nil },
    },
    ["upper_blackrock_spire"] = {
        { 4788, nil, 40, 58, "勘查員詹斯·鐵靴", "塔納利斯 - 熱砂港 66,23", "失落的摩沙魯石板", false, {5065}, nil, "把第五、第六塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。", "第 5 塊石板在暗影獵手沃什加斯的房間，第 6 塊在戰爭大師沃恩的房間。獎勵來自《面對葉基亞》；葉基亞就在詹斯·鐵靴旁邊。", {{40,1}, {54,2}, {56,3}, {61,4}, {69,5}}, {12740, 12741}, nil, 10460, "勘查員詹斯·鐵靴", { xp = 7750 } },
        { 8181, nil, 40, 58, "勘查員詹斯·鐵靴", "塔納利斯 - 熱砂港 66.9,24", "失落的摩沙魯石板", false, {4788}, {20218, 20219}, "去塔納利斯找葉基亞，當面質問哈卡之蛋的下落。", "哈卡鏈收尾一環：熱砂港的詹斯·鐵靴(66.9,24)接，交任務在旁邊的葉基亞(67,22.4)。鏈：尖嘯者的靈魂→摩沙魯的預言→…→失落的摩沙魯石板→本任務；後續為《拉斯塔哈之手》。", {{40,1}, {54,2}, {56,3}}, nil, nil, 10460, "勘查員詹斯·鐵靴", { xp = 6200 } },
        { 6502, "A", 50, 60, "哈爾琳", "冬泉谷", "巨龍之眼", false, {6501}, {16309}, nil, nil, {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10929, "哈爾琳", { xp = 8300 } },
        { 4729, nil, 55, 59, "基布雷爾", "燃燒平原 - 烈焰峯 65,22", nil, false, nil, {12264}, "到黑石塔捕捉血斧座狼幼崽：用籠子收服這些小傢伙，把籠中的幼崽交給基布雷爾。", "座狼幼崽在副本內。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12263, 12262}, nil, 10260, "基布雷爾", { xp = 6400, money = 9000 } },
        { 4862, nil, 55, 59, "基布雷爾", "燃燒平原 - 烈焰峯 65,22", nil, false, nil, {12529}, "到黑石塔替基布雷爾收集 15 枚尖塔蜘蛛卵。", "蜘蛛卵在副本內。拾卵時會隨機刷出小蜘蛛，傷害高還帶 AOE，留意。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12530}, nil, 10260, "基布雷爾", { xp = 6400, money = 9000 } },
        { 4866, nil, 55, 60, "狼狽不堪的約翰", "燃燒平原 - 烈焰峯 65,23", nil, false, nil, {15873}, "在黑石塔中心找到煙網蛛後，與她戰鬥讓她向你體內注入毒汁；有能力就順手殺了她。中毒後回狼狽不堪的約翰那裏，讓他把「蛛後的乳汁」抽出來。", "煙網蛛後在副本內。注意：中途解毒會導致任務失敗。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9563, "狼狽不堪的約翰", { xp = 9950, money = 18000 } },
        { 4974, "H", 55, 60, "薩爾", "奧格瑞瑪 31,38", "伊崔格的智慧", false, {4941}, {13966, 13968, 13965}, "到黑石塔擊殺大酋長雷德·黑手，帶着他的頭顱返回奧格瑞瑪。", "雷德·黑手在副本內。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12630}, nil, 4949, "薩爾", { xp = 9950, money = 27000, rep = { {76, 200, "奧格瑞瑪"}, {530, 200, "暗矛巨魔"}, {68, 200, "幽暗城"}, {81, 200, "雷霆崖"} } } },
        { 4982, "H", 55, 59, "比修", "下層黑石塔", "狡猾的比修", true, {4981}, nil, "找回比修的裝置還給她——她記得藏在城市最底層。", "裝置在通往煙網蛛後的路上。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "比修", { xp = 6400 } },
        { 4983, "H", 55, 59, "比修", nil, nil, true, {4982}, {15858, 15859}, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12652}, nil, 10257, "比修", { xp = 6400, money = 18000, rep = { {76, 100, "奧格瑞瑪"} } } },
        { 5001, "A", 55, 59, "比修", "下層黑石塔", nil, true, nil, nil, "找回比修的裝置還給她。祝你好運！", "裝置在通往煙網蛛後的路上。後續找麥克斯韋元帥(燃燒平原-摩根的崗哨 84,58)。", {{55,2}, {57,3}, {62,4}, {71,5}}, {12345}, nil, 10257, "比修", { xp = 6400 } },
        { 5002, "A", 55, 59, "比修", nil, nil, true, {5001}, nil, nil, nil, {{55,2}, {57,3}, {62,4}, {71,5}}, {12770}, nil, 10257, "比修", { xp = 6400, money = 18000, rep = { {72, 100, "暴風城"} } } },
        { 5047, nil, 55, 60, "芬克·恩霍爾", "上層黑石塔", nil, true, nil, nil, "與永望鎮的瑪雷弗斯·暗錘談一談。", "剝完比斯巨獸的皮後芬克·恩霍爾纔會出現。瑪雷弗斯·暗錘(冬泉谷-永望鎮 61,38)。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12710}, nil, 10776, "皮普·急智", { xp = 6600 } },
        { 5102, "A", 55, 60, "麥克斯韋爾元帥", "燃燒平原 - 摩根的崗哨 82,68", "達基薩斯將軍的命令", false, {5089}, {13966, 13968, 13965}, "到黑石塔擊殺達基薩斯將軍，回麥克斯韋爾元帥處覆命。", "達基薩斯將軍在副本內。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 9560, "麥克斯韋爾元帥", { xp = 9950, money = 27000, rep = { {469, 200, "聯盟"} } } },
        { 5127, nil, 55, 60, "羅拉克斯", "冬泉谷 64,74", "羅拉克斯的故事", false, {5126}, {12696, 9224, 12849}, "到黑石塔找到古拉魯克，殺死後用血污長矛刺入屍體吸乾靈魂煉成穿魂長矛；再找一塊未鑄造的符文覆飾胸甲，把兩樣都交給冬泉谷的羅拉克斯。", "鍛造任務。古拉魯克在副本內。需要鍛造 270 才能接。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {12847, 12806, 12848}, nil, 10918, "羅拉克斯", { xp = 8300 } },
        { 6569, "H", 55, nil, "巫女麥蘭達", "西瘟疫之地 50,77", "幻術的欺詐", false, {6568}, nil, "到黑石塔收集 20 顆黑色龍人的眼球，回巫女麥蘭達處覆命。", "黑龍系的敵人都會掉眼球。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16786}, nil, 11872, "巫女麥蘭達", { xp = 6600 } },
        { 6602, "H", 55, 60, "羅卡魯", "淒涼之地 - 葬影村 25,71", "晉升……", false, {6601}, {16309}, "到黑石塔擊殺達基薩斯將軍，把他的血交給羅卡魯。", "奧妮克西亞前置的最後一步。達基薩斯將軍在副本內。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {16663}, nil, 10182, "雷克薩", { xp = 9950 } },
        { 6821, nil, 55, nil, "海達克西斯公爵", "艾薩拉 79,73", "被囚禁的水元素", false, nil, nil, "把艾博希爾之眼交給艾薩拉的海達克西斯公爵。", "艾博希爾在副本內。3.0.8 補丁後無法再開啓這條任務線；已接到的不受影響，仍可完成。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {17322}, nil, 13278, "海達克西斯公爵", nil },
        { 7761, nil, 55, nil, nil, "黑手的命令掉落自（副本入口地圖）裂盾軍需官。", nil, false, nil, nil, "真是頭蠢獸人——找到那枚烙印，拿到達基薩斯徽記，才能使用命令寶珠。", "黑翼之巢的進門任務。裂盾軍需官在黑石塔副本門口右側附近；寶珠在達基薩斯將軍身後。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {18987}, nil, nil, nil, nil },
        { 4734, nil, 57, 60, "丁奇·斯迪波爾", "燃燒平原 - 烈焰峯 65,24", "丁奇·斯迪波爾", false, {4907}, {12144}, "在孵化間對一顆龍蛋使用龍蛋冷凍器初號機。", "龍蛋在烈焰之父的房間。凍蛋後別去點蛋，直接用背包裏的裝置；打完達基薩斯將軍後可以直接跳下龍蛋房單獨補做。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12286}, nil, 10267, "丁奇·斯迪波爾", { xp = 8300, money = 18000, rep = { {169, 150, "熱砂港"} } } },
        { 4735, nil, 57, 60, "丁奇·斯迪波爾", "燃燒平原 - 烈焰峯 65,24", "冷凍龍蛋", false, {4734}, nil, "把電動採集模塊和 8 顆龍蛋交給燃燒平原烈焰峯的丁奇·斯迪波爾。", "龍蛋都在烈焰之父的房間裏。凍住蛋後靠近使用背包裏的裝置即可（不用點蛋）；團裏沒人管的話，打完將軍跳下龍蛋房可單獨補做。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12241, 12287}, nil, 10267, "丁奇·斯迪波爾", { xp = 9950, money = 27000, rep = { {169, 200, "熱砂港"} } } },
        { 4743, nil, 57, 60, "裂盾滲透者", nil, "晉升印章", true, {4742}, {12344}, nil, "在龍下方的水中使用未鑄造的印章開啓鑄印事件。事件一次只出 1 枚可拾取的鍛造印章，且龍有 3 小時冷卻——一晚只能做一個人。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12324, 12339}, nil, 10299, "裂盾滲透者", { xp = 9950 } },
        { 4764, "A", 57, 60, "瑪亞拉·布萊特文", "燃燒平原 - 摩根的崗哨 84,69", "瑪亞拉·布萊特文", false, {4766}, nil, "把末日釦環交給燃燒平原的瑪亞拉·布萊特文。", "前置可從雷明頓·瑞治維爾伯爵接(暴風城-暴風要塞 77,47)。釦環在烈焰之父房間的箱子裏。箱子約 20 秒刷新一次，多人可輪流開。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12352}, nil, 9565, "瑪亞拉·布萊特文", { xp = 1650, rep = { {72, 25, "暴風城"} } } },
        { 4765, "A", 57, 60, "瑪亞拉·布萊特文", "燃燒平原", nil, false, {4764}, {15861, 15860}, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {12437}, nil, 9565, "瑪亞拉·布萊特文", { xp = 6600, money = 27000, rep = { {72, 100, "暴風城"} } } },
        { 4768, "H", 57, 60, "薇薇安·拉格雷", "荒蕪之地 - 卡加斯 2,47", "薇薇安·拉格雷和黑暗石板", false, {4769}, {15861, 15860}, "把黑暗石板交給卡加斯的暗法師薇薇安·拉格雷。", "前置可從藥劑師金格接(幽暗城-鍊金房 50,68)。石板在上層黑石塔的龍蛋房（孵化場）。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12358}, nil, 9078, "暗法師薇薇安·拉格雷", { xp = 8300, money = 27000, rep = { {68, 150, "幽暗城"} } } },
        { 5160, nil, 57, 60, "奧比", "上層黑石塔", nil, true, nil, nil, "到冬泉谷找到哈爾琳，把奧比的鱗片交給她。", "奧比在競技場旁的房間，蹲在一處凸臺上。哈爾琳(冬泉谷 54,51)；從洞穴最裏面的傳送符文站上去就能到她身邊。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12923}, nil, 10740, "奧比", { xp = 6600 } },
        { 8966, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖[D]", "重要的材料", false, {8962}, nil, "用召喚火盆召出莫爾·灰蹄的靈魂並殺掉他，把火盆和瓦塔拉克飾品左瓣帶回黑石山交給伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。莫爾·灰蹄在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {21984, 22049}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8989, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖[D]", "更多重要的材料", false, {8986}, nil, "在比斯巨獸的房間用召喚火盆召出瓦塔拉克公爵，殺死後對屍體使用瓦塔拉克的飾品，再把飾品還給瓦塔拉克公爵之魂。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。莫爾·灰蹄在副本內召喚。", {{58,3}, {63,4}, {72,5}}, {22048, 22049}, nil, 16033, "伯德雷", { xp = 8300 } },
        { 8994, nil, 58, nil, "伯德雷", "黑石山 副本入口地圖[D]", "瓦塔拉克飾品的右瓣", false, {8989}, nil, "從黑石塔的獸人身上收集 40 副黑石護腕，連同 1 瓶超級能量合劑一起交給黑石山的伯德雷。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。護腕由黑石塔獸人掉落；超級能量合劑是鍊金製品。", {{58,3}, {63,4}, {72,5}}, {22138, 13512, 22048}, nil, 16033, "伯德雷", nil },
        { 8995, nil, 58, 60, "伯德雷", "黑石山 副本入口地圖[D]", "最後的準備", false, {8994}, nil, "在比斯巨獸的房間用召喚火盆召出瓦塔拉克公爵，殺死後對屍體使用瓦塔拉克的飾品，再把飾品還給瓦塔拉克公爵之魂。", "需要超維度幽靈顯形器才能看到伯德雷（從《尋找安泰恩》獲得）。瓦塔拉克公爵在副本內召喚；獎勵向伯德雷領取。", {{58,3}, {63,4}, {72,5}}, {22048, 22056}, nil, 16033, "伯德雷", { xp = 9950 } },
    },
    ["onyxias_lair"] = {
        { 4182, "A", 48, 54, "赫林迪斯·河角", "燃燒平原 - 摩根的崗哨 85.6,69", nil, false, nil, nil, "獵殺燃燒平原的黑龍人，向赫林迪斯·河角覆命。", "聯盟開門鏈第一步。黑龍蛋、黑龍幼崽是非精英，黑龍人、黑翼龍人是 50-54 精英，建議組隊；都集中在地圖東部邊緣一線。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 9562, "赫林迪斯·河角", nil },
        { 4183, "A", 48, 54, "赫林迪斯·河角", "燃燒平原 - 摩根的崗哨 85.6,69", nil, false, {4182}, nil, "把赫林迪斯·河角的信送到赤脊山湖畔鎮的所羅門鎮長手中。", "同名任務共五段，從湖畔鎮一路輾轉推進到暴風城。本段終點：湖畔鎮市政廳(赤脊山 30,44)。", {{48,1}, {50,2}, {52,3}, {57,4}, {65,5}}, nil, nil, 344, "所羅門鎮長", nil },
        { 4241, "A", 50, 58, "麥克斯韋爾元帥", "燃燒平原 - 摩根的崗哨 84.6,68.8", nil, false, {4183}, nil, "到黑石深淵監獄探視被囚的溫德索爾元帥，把麥克斯韋爾元帥的信交給他。", "溫德索爾在深淵監獄區右側走廊盡頭的牢房裏。◎ 注意區分：麥克斯韋爾元帥在燃燒平原的摩根的崗哨，溫德索爾元帥在深淵牢裏。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 9023, "溫德索爾元帥", nil },
        { 6402, "A", 50, 60, "麥克斯韋爾元帥", "燃燒平原 - 摩根的崗哨 84.6,68.8", nil, false, {4322}, nil, "到暴風城門口找侍從羅威，召出雷吉納德·溫德索爾，護送他從城門走到暴風要塞。", "護送全程約 10 分鐘；若別的隊伍正在護送，溫德索爾會說他暫時脫不開身，等幾分鐘就會現身。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 12580, "雷吉納德·溫德索爾", nil },
        { 6403, "A", 50, 60, "雷吉納德·溫德索爾", "暴風城 - 城門 70.4,85.6", nil, false, {6402}, nil, "陪雷吉納德·溫德索爾行進到暴風要塞，擊殺卡特拉娜·普瑞斯托現形後召出的精英龍人衛兵，向伯瓦爾·弗塔根公爵覆命。", "假面遊行：普瑞斯托女男爵現出奧妮克希亞原形並召喚精英龍人衛兵，場邊的衛兵 NPC 會幫忙抗怪，全清後交任務。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 1748, "伯瓦爾·弗塔根公爵", nil },
        { 6501, "A", 50, 60, "伯瓦爾·弗塔根公爵", "暴風城", nil, false, {6403}, nil, "帶着龍眼碎片到冬泉谷南部的馬茲索里爾洞穴深處，找僞裝成人類的巨龍哈爾琳。", "哈爾琳在洞穴盡頭的傳送符文處，踩上符文就會傳到她身邊。洞裏精英龍人很多：組隊清過去、盜賊潛行、或開疾跑直接衝，都能到她跟前。", {{50,1}, {54,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 10929, "哈爾琳", nil },
        { 4941, "H", 55, 60, "高圖斯", "荒蕪之地 - 卡加斯 5.8,47.6", nil, false, {4903}, nil, "到奧格瑞瑪智慧谷找伊崔格談話，再把他的話帶給薩爾。", "伊崔格在智慧谷(34.4,38.4)，談完直接回薩爾(奧格瑞瑪 31,38)交任務。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 4949, "薩爾", nil },
        { 6566, "H", 55, 60, "薩爾", "奧格瑞瑪 31,38", nil, false, {4974}, nil, "聽薩爾講完黑龍的故事，向他覆命。", "純對話任務，站着聽完就行。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 4949, "薩爾", nil },
        { 6567, "H", 55, 60, "薩爾", "奧格瑞瑪 31,38", nil, false, {6566}, nil, "到淒涼之地尋找部落的勇士雷克薩。", "雷克薩沿石爪山脈至菲拉斯的大道來回巡邏，中途會穿過科多獸墓地；找不到就問淒涼之地綜合頻道，或從菲拉斯沿路往北走最容易堵到他。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10182, "雷克薩", nil },
        { 6568, "H", 55, 60, "雷克薩", "淒涼之地 - 通往菲拉斯的大道", nil, false, {6567}, nil, "把雷克薩的囑託送到西瘟疫之地烏瑟爾之墓附近的巫女麥蘭達手中。", "麥蘭達(西瘟疫之地 50,77)，她會教你僞裝成黑龍軍團成員的辦法。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11872, "巫女麥蘭達", nil },
        { 6570, "H", 55, 60, "巫女麥蘭達", "西瘟疫之地 50,77", nil, false, {6569}, nil, "戴上龍族僞裝護符，到塵泥沼澤最南端的洞穴裏與埃博斯塔夫對話。", "進洞走到最深處先使用「龍族僞裝護符」，再與埃博斯塔夫說話。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6582, "H", 55, 60, "埃博斯塔夫", "塵泥沼澤 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6570}, nil, "擊殺冬泉谷馬茲索里爾洞穴裏的藍龍斯克萊爾，取回頭骨交給埃博斯塔夫。", "《顱骨試煉》三場順序隨意、可以團殺；斯克萊爾(馬茲索里爾洞穴深處 53.2,56)，洞口(冬泉谷-馬茲索里爾洞穴 57,50)，要清不少精英龍人。◎ 三條龍都別忘摸頭骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6583, "H", 55, 60, "埃博斯塔夫", "塵泥沼澤 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6570}, nil, "擊殺悲傷沼澤的綠龍索姆努斯，取回頭骨交給埃博斯塔夫。", "索姆努斯在地圖東南部大範圍巡邏(約 80,70 附近)，先清一片區域等他路過。他有很強的擊退，自然抗性很喫香。三場試煉順序隨意，記得摸頭骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6584, "H", 55, 60, "埃博斯塔夫", "塵泥沼澤 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6570}, nil, "擊殺塔納利斯時光洞穴外的青銅龍克羅納利斯，取回頭骨交給埃博斯塔夫。", "克羅納利斯在時光洞穴門口(64.6,50.2)。三場試煉順序隨意、可以團殺，記得摸頭骨。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6585, "H", 55, 60, "埃博斯塔夫", "塵泥沼澤 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6582, 6583, 6584}, nil, "擊殺溼地的紅龍阿克特羅茲，取回頭骨交給埃博斯塔夫。", "前三場顱骨試煉交完纔會開放。阿克特羅茲在格瑞姆巴託附近巡邏(約 85,49)，火焰免疫；想剝皮需要剝皮技能 310。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10321, "埃博斯塔夫", nil },
        { 6601, "H", 55, 60, "埃博斯塔夫", "塵泥沼澤 - 埃博斯塔夫的洞穴 56.8,87.4", nil, false, {6585}, nil, "帶着暗淡的龍火護符去淒涼之地找雷克薩。", "任務描述讓你回黑石塔找達基薩斯將軍，但僞裝護符在黑石塔裏不生效——直接去淒涼之地找雷克薩（巡邏路線同《部落的勇士》）。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10182, "雷克薩", nil },
    },
}

